  async function loadPage(id){try{if(id==='dashboard')await loadExecutiveDashboard();if(id==='my-space')await loadDashboard();if(id==='employees')await loadEmployees();if(id==='employee-report')loadEmployeeReportPage();if(id==='organization')await loadOrganizationStructure();if(id==='branches')await loadBranches();if(id==='attendance')await loadAttendance();if(id==='shifts')await loadShifts();if(id==='leaves')await loadLeaves();if(id==='overtime')await loadOvertime();if(id==='evaluations')await loadEvaluation();if(id==='notifications')await loadNotifications();if(id==='communications')await loadCommunications();if(id==='payroll')await loadPayroll();if(id==='certificate-verification'){await loadSalaryCertificateWorkspace();$('#certificateVerificationCode').focus()}if(id==='advances')await loadAdvances();if(id==='lifecycle')await loadLifecycle();if(id==='reports')await loadReports();if(id==='access-control')await loadAccessControl();if(id==='settings'){fillOrganizationForm();await loadReferences();await Promise.all([loadCardSettingsPreview(),hasPermission('org.manage')?loadVisualIdentityStudio():Promise.resolve(),hasPermission('smtp.manage')?loadSmtpSettings():Promise.resolve(),hasPermission('reference.manage')?loadGoalTemplateSettings():Promise.resolve(),hasPermission('leave.approve')?loadLeaveHolidays():Promise.resolve()])}enforceDynamicPermissions($('.page.active'))}catch(error){alertMessage(apiError(error),true)}}

  async function loadDashboard(){const data=await api('/api/me/dashboard');state.dashboard=data;const e=data.employee||{},salary=data.salary||{},salaryHasAdvance=Number(salary.advance||0)>0;$('#welcomeTitle').textContent='مرحباً، '+(e.name||e.full_name||state.user.name||'');const balances=items(data.leave_balances),annual=balances.find(b=>b.code==='annual'||String(b.name||'').includes('سنوية')),annualAvailable=Number(annual?.available??annual?.balance??0);const unread=Number(data.notifications_unread||0);$('#myMetrics').innerHTML=[['الراتب الحالي',money(salary.net??e.salary??0),salaryHasAdvance?`بعد خصم سلفة ${money(salary.advance)}`:'الإجمالي الكامل'],['رصيد الإجازة السنوية',digits(annualAvailable)+' يوم','المتاح حالياً'],['طلبات الإجازة',digits(items(data.leave_requests).length),'آخر الطلبات'],['إشعارات غير مقروءة',digits(unread),'رسائل موجهة إليك']].map(metricHtml).join('');const photo=e.photo_data||e.photo_url,certButton=hasPermission('salary_certificate.issue')?'<button class="text-btn" data-my-cert>إصدار شهادة راتب</button>':'<button class="text-btn" data-my-cert-request>طلب شهادة راتب</button>';$('#myCardSummary').innerHTML=`<span class="avatar">${photo?`<img src="${esc(photo)}" alt="صورة الموظف">`:esc(initials(e.name||e.full_name))}</span><div><b>${esc(e.name||e.full_name||state.user.name)}</b><small>${esc(e.employee_no||e.employee_number||e.code||'—')} · ${esc(e.job_title||e.title||'—')}</small><small>${esc(e.department_name||e.department||'—')} · ${esc(e.branch_name||e.branch||'—')}</small></div><div class="summary-actions"><button class="text-btn" data-employee-id="${e.id}">ملفي ومستنداتي</button><button class="text-btn" data-my-card>البطاقة</button>${certButton}</div>`;const a=data.attendance_today;$('#lastPunch').textContent=a?`الدخول: ${clockText(a.check_in_at||a.check_in_time||a.check_in)} · الخروج: ${clockText(a.check_out_at||a.check_out_time||a.check_out)}`:'لا يوجد تسجيل اليوم';$('#punchHeadline').textContent=a?.check_in_at&&!a?.check_out_at?'أنت مسجل داخل الدوام':'تحقق من موقعك للتسجيل';renderMyRequests(items(data.leave_requests).concat(items(data.overtime_requests)));if(!hasPermission('salary_certificate.issue'))try{const requests=items(await api('/api/salary-certificates/requests'));const latest=requests[0];if(latest)$('#myCardSummary').insertAdjacentHTML('beforeend',`<small class="certificate-request-status">طلب الشهادة: ${esc(salaryCertificateStatus(latest.request_status))}</small>`)}catch(_){}try{const inbox=await api('/api/notifications/inbox');state.notifications=items(inbox)}catch(_){state.notifications=[]}renderMyNotifications();updateUnread(unread)}
  async function loadExecutiveDashboard(){
    const form=$('#dashboardFilters');if(!form.date_to.value){const now=new Date(),from=new Date(now);from.setDate(from.getDate()-29);form.date_to.value=now.toISOString().slice(0,10);form.date_from.value=from.toISOString().slice(0,10)}
    if(!state.branches.length||!state.departments.length){const [branches,departments]=await Promise.all([api('/api/branches'),api('/api/departments')]);state.branches=items(branches);state.departments=items(departments);const branchValue=form.branch_id.value,departmentValue=form.department_id.value;form.branch_id.innerHTML='<option value="">كل الفروع المتاحة</option>'+state.branches.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');form.department_id.innerHTML='<option value="">كل الأقسام المتاحة</option>'+state.departments.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');form.branch_id.value=branchValue;form.department_id.value=departmentValue}
    const query=new URLSearchParams();['date_from','date_to','branch_id','department_id'].forEach(key=>{if(form.elements[key].value)query.set(key,form.elements[key].value)});const data=await api('/api/dashboard?'+query);state.executiveDashboard=data;renderExecutiveDashboard(data)
  }
  function renderExecutiveDashboard(data){const m=data.metrics||{},attendanceContext=data.attendance_context||{},selectedDate=data.filters?.date_to,dateLabel=attendanceContext.label==='اليوم'?'اليوم':dateText(selectedDate);$('#dashboardAsOf').textContent=i18n()?.formatDate(data.as_of,{dateStyle:'medium',timeStyle:'short'});$('#dashboardPulse').innerHTML=items(data.pulse).map(item=>`<div><small>${esc(item.label)}</small><b>${digits(item.value)}</b></div>`).join('');const attendanceNote=`${digits(m.absent_today)} غياب مستحق · من ${digits(m.eligible_to_attend||0)}`,metrics=[['إجمالي الموظفين',m.employees_total,'النطاق المحدد','people'],['القوة النشطة',m.employees_active,`${digits(m.employees_inactive)} غير نشط`,'active'],['حضور '+dateLabel,m.attendance_today,attendanceNote,'time'],['التأخير',m.late_today,'حسب المناوبات','late'],['الإجازات المعلقة',m.leave_pending,'تحتاج قراراً','request'],['الإضافي المعلق',m.overtime_pending,'تحتاج قراراً','request'],['وثائق قريبة الانتهاء',m.documents_expiring,'خلال ٦٠ يوماً','risk'],['صافي المسيرات',money(m.payroll_net),`${digits(m.payroll_runs)} مسير`,'money'],['موظفون جدد',m.new_employees,'داخل النطاق الزمني','people'],['سلف نشطة',m.advance_active,'مقدمة أو معتمدة','money']];$('#executiveMetrics').innerHTML=metrics.map(([label,value,note,tone])=>`<article class="executive-metric ${tone}"><small>${esc(label)}</small><b>${typeof value==='number'?digits(value):esc(value)}</b><span>${esc(note)}</span></article>`).join('');renderDistribution($('#departmentDistribution'),items(data.distributions?.departments));renderDistribution($('#branchDistribution'),items(data.distributions?.branches));const health=data.health||{};$('#healthScore').textContent=digits(health.score||0);$('#healthStatus').textContent=health.status||'—';const healthContext=$('#healthContext');if(healthContext)healthContext.textContent=`المستحقون ${digits(m.eligible_to_attend||0)} · راحة ${digits(attendanceContext.weekly_rest||0)} · إجازة ${digits(attendanceContext.approved_leave||0)} · لم يحن دوامهم ${digits(attendanceContext.not_due_yet||0)}`;$('#healthProgress').style.width=`${Math.max(0,Math.min(100,Number(health.score)||0))}%`;const actionIcons={employees:'users',attendance:'clock',leaves:'calendar',overtime:'overtime',payroll:'wallet',evaluations:'target',reports:'report',communications:'mail',settings:'settings',branches:'map'};$('#dashboardActions').innerHTML=items(data.quick_actions).length?items(data.quick_actions).map(x=>`<button class="quick-action" type="button" data-goto="${esc(x.route)}">${icon(actionIcons[x.route]||'chevron')}<span>${esc(x.label)}</span></button>`).join(''):emptyState('لا توجد إجراءات ضمن صلاحياتك.','shield');$('#dashboardActivity').innerHTML=items(data.activity).length?items(data.activity).map(x=>`<div class="event"><span></span><div><b>${esc(auditLabel(x.action))}</b><small>${esc(x.actor_name)} · ${i18n()?.formatDate(x.created_at,{dateStyle:'short',timeStyle:'short'})}</small></div></div>`).join(''):emptyState('لا يوجد نشاط مسجل.','report')}
  function renderDistribution(root,list){const max=Math.max(1,...list.map(x=>Number(x.value)||0));root.innerHTML=list.length?list.map(x=>`<div class="distribution-row"><div><span>${esc(x.label)}</span><b>${digits(x.value)}</b></div><i><span style="width:${Math.round(Number(x.value)*100/max)}%"></span></i></div>`).join(''):emptyState('لا توجد بيانات في هذا النطاق.','report')}
  function auditLabel(value){const labels={'auth.login':'تسجيل دخول','attendance.check_in':'تسجيل حضور','attendance.check_out':'تسجيل انصراف','leave.approved':'اعتماد إجازة','overtime.approved':'اعتماد عمل إضافي','employee.create':'إضافة موظف','communications.campaign_create':'إطلاق حملة بريدية','security.permissions_update':'تحديث صلاحيات'};return labels[value]||String(value||'نشاط نظام').replaceAll('.',' · ')}

  async function loadCommunications(){const response=await api('/api/communications/campaigns');state.campaigns=items(response);const queued=state.campaigns.filter(x=>x.status==='queued').length,failed=state.campaigns.reduce((sum,x)=>sum+Number(x.failed_count||0),0),sent=state.campaigns.reduce((sum,x)=>sum+Number(x.sent_count||0),0);$('#campaignMetrics').innerHTML=[['الحملات',digits(state.campaigns.length),'كل السجل'],['رسائل مرسلة',digits(sent),'تسليم ناجح'],['بانتظار الإرسال',digits(queued),'صندوق التطوير أو الطابور'],['متعثر',digits(failed),'قابل لإعادة المحاولة']].map(metricHtml).join('');$('#campaignList').classList.remove('loading-block');$('#campaignList').innerHTML=state.campaigns.length?state.campaigns.map(x=>`<div class="campaign-row"><span class="campaign-icon">${icon('mail')}</span><div><h3>${esc(x.subject)}</h3><p>${esc(x.body).slice(0,150)}</p><small>${esc(x.sender_name)} · ${dateText(String(x.created_at).slice(0,10))} · ${digits(x.recipient_count)} مستلم</small></div><div class="campaign-state"><span class="status ${statusClass(x.status)}">${esc(statusLabel(x.status))}</span><button class="text-btn" data-campaign-open="${x.id}">سجل التسليم</button>${hasPermission('communications.retry')&&x.status!=='sent'?`<button class="secondary" data-campaign-retry="${x.id}">إعادة المحاولة</button>`:''}</div></div>`).join(''):emptyState('لا توجد حملات بريدية بعد.','mail')}
  async function campaignModal(){if(!state.employees.length||!state.departments.length||!state.branches.length){const [employees,departments,branches]=await Promise.all([api('/api/employees'),api('/api/departments'),api('/api/branches')]);state.employees=items(employees);state.departments=items(departments);state.branches=items(branches)}openModal('رسالة بريدية جديدة',`<form id="campaignForm"><div class="campaign-composer"><div><div class="form-grid"><label>نطاق المستلمين<select name="audience_type"><option value="all">جميع الموظفين النشطين</option><option value="department">قسم محدد</option><option value="branch">فرع محدد</option><option value="employee">موظف واحد</option></select></label><label>التحديد<select name="audience_ref" disabled><option value="">يحدد تلقائياً للجميع</option></select></label><label class="span-2">الموضوع<input name="subject" maxlength="200" required></label><label>القالب<select name="template"><option value="plain">رسالة مؤسسية</option><option value="announcement">إعلان</option><option value="policy">سياسة</option><option value="congratulation">تهنئة</option></select></label><label>عدد المستلمين<span class="recipient-count" id="campaignRecipientCount">—</span></label><label class="span-2">نص الرسالة<textarea name="body" rows="10" maxlength="5000" required placeholder="اكتب رسالة نصية آمنة وواضحة…"></textarea></label></div><button class="primary" type="submit">إرسال الآن</button></div><aside class="campaign-preview"><span class="eyebrow">معاينة آمنة</span><h3 id="campaignPreviewSubject">موضوع الرسالة</h3><p id="campaignPreviewBody">سيظهر النص هنا كما سيصل إلى الموظف.</p><small class="org-name">المؤسسة</small></aside></div></form>`,true);updateCampaignAudience($('#campaignForm'))}
  function updateCampaignAudience(form){const type=form.audience_type.value,select=form.audience_ref;let choices=[];if(type==='employee')choices=state.employees.map(x=>[x.id,`${x.full_name} — ${x.employee_no}`]);if(type==='department')choices=state.departments.map(x=>[x.id,x.name]);if(type==='branch')choices=state.branches.map(x=>[x.id,x.name]);select.disabled=type==='all';select.innerHTML=type==='all'?'<option value="">كل الموظفين النشطين</option>':choices.map(x=>`<option value="${x[0]}">${esc(x[1])}</option>`).join('');updateCampaignCount(form)}
  function updateCampaignCount(form){const type=form.audience_type.value,ref=String(form.audience_ref.value||''),count=state.employees.filter(x=>x.active&&x.email&&(type==='all'||type==='employee'&&String(x.id)===ref||type==='department'&&String(x.department_id)===ref||type==='branch'&&String(x.branch_id)===ref)).length;$('#campaignRecipientCount').textContent=digits(count)+' موظفاً لديهم بريد'}
  async function saveCampaign(form){const button=$('button[type=submit]',form);setBusy(button,true,'جارٍ إنشاء سجل التسليم…');try{await api('/api/communications/campaigns',{method:'POST',body:{audience_type:form.audience_type.value,audience_ref:form.audience_ref.value||null,subject:form.subject.value,body:form.body.value,template:form.template.value}});closeModal();toast('تم إنشاء الحملة وتسجيل حالة كل مستلم');await loadCommunications()}catch(error){alertMessage(apiError(error),true)}finally{setBusy(button,false)}}
  async function openCampaign(id){const data=await api('/api/communications/campaigns/'+id),c=data.campaign;openModal('سجل تسليم الحملة',`<div class="campaign-detail"><h3>${esc(c.subject)}</h3><p>${esc(c.body)}</p><div class="metric-grid compact">${[['المستلمون',c.recipient_count,''],['تم الإرسال',c.sent_count,''],['متعثر',c.failed_count,'']].map(metricHtml).join('')}</div><div class="table-wrap"><table><thead><tr><th>الموظف</th><th>البريد</th><th>الحالة</th><th>المحاولات</th></tr></thead><tbody>${items(c.deliveries).map(x=>`<tr><td>${esc(x.employee_name)}</td><td dir="ltr">${esc(x.to_email)}</td><td><span class="status ${statusClass(x.status)}">${esc(statusLabel(x.status))}</span></td><td>${digits(x.attempts)}</td></tr>`).join('')}</tbody></table></div></div>`,true)}

  async function loadAccessControl(){const [users,catalog]=await Promise.all([api('/api/admin/users'),api('/api/admin/permissions/catalog')]);state.adminUsers=items(users);state.permissionGroups=items(catalog.groups||catalog);renderAccessUsers();const filter=$('#permissionGroupFilter');filter.innerHTML=`<option value="">${tr('كل مجموعات الصلاحيات')}</option>`+state.permissionGroups.map(g=>`<option value="${esc(g.key)}">${esc(tr(g.label))}</option>`).join('')}
  function renderAccessUsers(){const q=$('#accessUserSearch').value.trim().toLowerCase(),list=state.adminUsers.filter(x=>!q||`${x.name} ${x.email} ${x.role} ${tr(roleLabels[x.role]||x.role)}`.toLowerCase().includes(q));$('#accessUserList').classList.remove('loading-block');$('#accessUserList').innerHTML=list.map(x=>`<button class="access-user ${String(state.selectedAccessUserId)===String(x.id)?'active':''}" type="button" data-access-user="${x.id}"><span class="avatar">${esc(initials(x.name))}</span><span><b>${esc(x.name)}</b><small>${esc(x.email)} · ${esc(tr(roleLabels[x.role]||x.role))}</small></span>${x.is_super_admin?`<em>${tr('محمي')}</em>`:''}</button>`).join('')||`<div class="empty">${tr('لا توجد نتائج.')}</div>`}
  function selectAccessUser(id){state.selectedAccessUserId=Number(id);renderAccessUsers();const user=state.adminUsers.find(x=>x.id===state.selectedAccessUserId);if(!user)return;$('#permissionEmpty').hidden=true;$('#permissionEditor').hidden=false;const protectedUser=user.is_super_admin;$('#permissionUserHead').innerHTML=`<div><span class="avatar">${esc(initials(user.name))}</span><span><b>${esc(user.name)}</b><small>${esc(user.email)} · ${esc(tr(roleLabels[user.role]||user.role))}</small></span></div><div class="button-row"><button class="secondary" type="button" data-reset-user="${user.id}" ${protectedUser?'disabled':''}>${tr('كلمة مرور مؤقتة')}</button><button class="${user.active?'danger':'secondary'}" type="button" data-toggle-user="${user.id}" ${protectedUser?'disabled':''}>${tr(user.active?'تعطيل الحساب':'تفعيل الحساب')}</button></div>`;renderPermissionMatrix(user)}
  function renderPermissionMatrix(user){const overrides=new Map(items(user.overrides).map(x=>[x.permission,x.granted?'grant':'deny'])),search=$('#permissionSearch').value.trim().toLowerCase(),groupFilter=$('#permissionGroupFilter').value;$('#permissionMatrix').innerHTML=state.permissionGroups.filter(g=>!groupFilter||g.key===groupFilter).map(group=>{const permissions=items(group.permissions).filter(p=>!search||`${p.key} ${p.label} ${tr(p.label)}`.toLowerCase().includes(search));if(!permissions.length)return'';return `<section class="permission-group" data-permission-group="${esc(group.key)}"><header><h3>${esc(tr(group.label))}</h3><span>${digits(permissions.length)} ${tr('صلاحية')}</span></header>${permissions.map(p=>{const mode=overrides.get(p.key)||'inherit',effective=user.permissions.includes(p.key)||user.permissions.includes('*'),reason=user.permission_reasons?.[p.key]||`role:${user.role}`;return `<div class="permission-row" data-permission-row><div><b>${esc(tr(p.label))}</b><code>${esc(p.key)}</code></div><div class="tri-state" role="radiogroup" aria-label="${esc(tr(p.label))}"><label><input type="radio" name="perm__${esc(p.key)}" value="inherit" ${mode==='inherit'?'checked':''} ${user.is_super_admin?'disabled':''}> ${tr('الدور')}</label><label><input type="radio" name="perm__${esc(p.key)}" value="grant" ${mode==='grant'?'checked':''} ${user.is_super_admin?'disabled':''}> ${tr('منح')}</label><label><input type="radio" name="perm__${esc(p.key)}" value="deny" ${mode==='deny'?'checked':''} ${user.is_super_admin?'disabled':''}> ${tr('منع')}</label></div><span class="effective-state ${effective?'allowed':'denied'}">${tr(effective?'فعّالة':'غير فعّالة')} · ${reasonLabel(reason)}</span></div>`}).join('')}</section>`}).join('');$('#effectivePermissionCount').textContent=user.is_super_admin?tr('مدير أعلى: كل الصلاحيات فعّالة'):digits(user.permissions.filter(x=>x!=='*').length)+' '+tr('صلاحية فعّالة')}
  function reasonLabel(reason){if(reason==='protected_super_admin')return tr('حساب محمي');if(reason==='explicit_grant')return tr('منح صريح');if(reason==='explicit_deny')return tr('منع صريح');return tr('الدور الأساسي')}
  async function savePermissions(form){const user=state.adminUsers.find(x=>x.id===state.selectedAccessUserId),overrides=[];$$('input[type="radio"]:checked',form).forEach(input=>{if(input.value!=='inherit')overrides.push({permission:input.name.replace('perm__',''),granted:input.value==='grant'})});try{const response=await api(`/api/admin/users/${user.id}/permissions`,{method:'PATCH',body:{overrides}});const index=state.adminUsers.findIndex(x=>x.id===user.id);state.adminUsers[index]=response.user;toast('تم حفظ الصلاحيات وتسجيل التغيير في سجل التدقيق');selectAccessUser(user.id)}catch(error){alertMessage(apiError(error),true)}}

  function openChangePassword(forced=false){state.forcePasswordChange=forced;openModal(forced?'تغيير كلمة المرور المؤقتة':'أمان الحساب',`<form id="changePasswordForm"><div class="security-callout">${forced?'عيّن كلمة مرور شخصية قبل فتح وحدات النظام.':'سيتم إنهاء كل الجلسات بعد نجاح التغيير.'}</div><div class="form-grid"><label class="span-2">كلمة المرور الحالية<input name="current_password" type="password" autocomplete="current-password" required autofocus></label><label>كلمة المرور الجديدة<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>تأكيد كلمة المرور<input name="confirm_password" type="password" autocomplete="new-password" minlength="10" required></label></div><p class="password-policy">١٠ أحرف على الأقل، حرف كبير وصغير، رقم ورمز خاص.</p><button class="primary" type="submit">تحديث كلمة المرور</button></form>`);if(forced)$('#closeModal').hidden=true}
  function forgotPasswordModal(){openModal('استرجاع كلمة المرور',`<form id="forgotPasswordForm"><p>أدخل بريدك المؤسسي. ستظهر النتيجة نفسها دائماً لحماية الحسابات.</p><label>البريد الإلكتروني<input name="email" type="email" required autofocus value="${esc($('#loginEmail').value)}"></label><button class="primary" type="submit">إرسال التعليمات</button></form>`)}
  async function openResetPassword(token){const response=await api('/api/auth/reset-password/validate',{method:'POST',body:{token}});openModal('تعيين كلمة مرور جديدة',response.valid?`<form id="resetPasswordForm"><input type="hidden" name="token" value="${esc(token)}"><div class="form-grid"><label>كلمة المرور الجديدة<input name="password" type="password" minlength="10" required autofocus></label><label>التأكيد<input name="confirm_password" type="password" minlength="10" required></label></div><p class="password-policy">الرابط صالح لمرة واحدة لمدة ٣٠ دقيقة.</p><button class="primary" type="submit">حفظ والعودة للدخول</button></form>`:`<div class="denied-inline"><b>الرابط غير صالح أو منتهي</b><p>اطلب رابط استرجاع جديداً من شاشة الدخول.</p><button class="secondary" type="button" data-close-modal>العودة</button></div>`)}
  async function loadSmtpSettings(){const data=await api('/api/admin/smtp'),s=data.smtp||{},form=$('#smtpForm');['smtp_host','smtp_port','smtp_username','smtp_from_name','smtp_from_email'].forEach(k=>form.elements[k].value=s[k]??'');form.smtp_password.value=s.smtp_password||'';form.smtp_tls.checked=Boolean(s.smtp_tls);form.smtp_ssl.checked=Boolean(s.smtp_ssl)}
