  async function showOutbox(){const response=await api('/api/admin/outbox');openModal('صندوق البريد الآمن',`<div class="stack">${items(response).map(x=>`<div class="list-item"><span class="campaign-icon">${icon('mail')}</span><div><h3>${esc(x.subject)}</h3><small>${esc(x.to_email)} · ${esc(x.kind)}</small><p>${esc(x.body)}</p></div><span class="status ${statusClass(x.status)}">${esc(statusLabel(x.status))}</span></div>`).join('')||emptyState('الصندوق فارغ.','mail')}</div>`,true)}
  function metricValue(value){const text=String(value??'');return i18n()?.locale==='en'?text.replace(/\s+يوم$/u,' '+tr('يوم')):text}
