    overview.insertAdjacentHTML('afterbegin',`<section class="profile-completeness" aria-label="${tr('اكتمال ملف الموظف')}"><div><span class="eyebrow">${tr('جاهزية الملف')}</span><b>${digits(completeness.percent)}٪</b><small>${tr('{filled} من {total} حقلاً أساسياً',{filled:digits(completeness.filled),total:digits(completeness.total)})}</small></div><span class="completeness-track"><i style="width:${Math.max(0,Math.min(100,Number(completeness.percent)||0))}%"></i></span>${completeness.percent<100?`<p>${tr('يمكن حفظ الملف الآن وإكمال البيانات الناقصة لاحقاً دون تعطيل الموظف.')}</p>`:`<p>${tr('جميع عناصر الملف الأساسية مكتملة.')}</p>`}</section>`);
    const actions=$('.profile-actions',overview);if(hasPermission('employee.profile.edit')){actions.querySelector('[data-profile-tab="card"]')?.classList.replace('primary','secondary');actions.querySelectorAll('[data-edit-reference],[data-assign-branch],[data-assign-shift]').forEach(button=>button.remove());actions.insertAdjacentHTML('afterbegin',`<button class="primary profile-edit-primary" data-edit-employee-profile="${employee.id}">${icon('edit')}${tr('تعديل ملف الموظف بالكامل')}</button>`)}
    const personal=`<section class="profile-panel" data-profile-panel="personal"><div class="section-head"><div><span class="eyebrow">${tr('هوية شخصية')}</span><h2>${tr('البيانات الشخصية')}</h2><p>${tr('بيانات محمية لا تظهر في القوائم أو البحث العام.')}</p></div></div><div class="profile-facts expanded">${profileDatum('تاريخ الميلاد',dateText(employee.birth_date),employee.age_years!=null?`${digits(employee.age_years)} ${tr('سنة')}`:'')}${profileDatum('الجنسية',employee.nationality)}${profileDatum('مكان الميلاد',employee.place_of_birth)}${profileDatum('الحالة الاجتماعية',maritalStatusLabel(employee.marital_status))}${profileDatum('رقم جواز السفر',employee.passport_no,dateText(employee.passport_expires_on))}${profileDatum('رقم الهوية الإماراتية',employee.emirates_id_no,dateText(employee.emirates_id_expires_on))}${profileDatum('المؤهل العلمي',employee.qualification)}${profileDatum('الهاتف',employee.phone)}${profileDatum('البريد الإلكتروني',employee.email)}</div></section>`;
    const employment=`<section class="profile-panel" data-profile-panel="employment"><div class="section-head"><div><span class="eyebrow">${tr('السجل الوظيفي')}</span><h2>${tr('العمل والعقد')}</h2><p>${tr('المرجع التنظيمي والعقدي المعتمد للموظف.')}</p></div></div><div class="profile-facts expanded">${profileDatum('الرقم الوظيفي',employee.employee_no)}${profileDatum('المسمى الوظيفي',employee.job_title)}${profileDatum('الدرجة الوظيفية',employee.job_grade_name||employee.job_grade)}${profileDatum('القسم',employee.department_name)}${profileDatum('الفرع',employee.branch_name)}${profileDatum('المدير المباشر',employee.manager_name)}${profileDatum('تاريخ التعيين',dateText(employee.hire_date),employee.service_years!=null?`${digits(employee.service_years)} ${tr('سنة خدمة')}`:'')}${profileDatum('حالة الملف',employee.active?tr('على رأس العمل'):tr('منتهية الخدمة'))}</div>${salaryBreakdownMarkup(employee)}<div class="profile-contract-note">${icon('certificate')}<div><b>${tr('صلاحية البطاقة مرتبطة بعقد العمل')}</b><p>${tr('يظهر للموظف تاريخ بداية العقد ونهايته ومدته فقط. محتوى العقد محفوظ للموارد البشرية أو من يملك صلاحية مستندات الموظفين.')}</p></div></div></section>`;
    const address=`<section class="profile-panel" data-profile-panel="address"><div class="section-head"><div><span class="eyebrow">${tr('العنوان الدائم')}</span><h2>${tr('بيانات السكن والمراسلات')}</h2><p>${tr('تفاصيل عملية للتواصل الرسمي عند الحاجة.')}</p></div></div>${addressText(employee)?`<div class="address-card">${icon('map')}<div><b>${esc(addressText(employee))}</b><small>${employee.address_po_box?`${tr('صندوق البريد')}: ${esc(employee.address_po_box)}`:tr('لا يوجد صندوق بريد مسجل')}</small><p>${esc(employee.address_notes||'')}</p></div></div>`:emptyState('لم يضف عنوان دائم بعد.','map')}<div class="profile-facts expanded">${profileDatum('الدولة',employee.address_country)}${profileDatum('الإمارة / المدينة',employee.address_city)}${profileDatum('المنطقة',employee.address_area)}${profileDatum('الشارع',employee.address_street)}${profileDatum('المبنى / الوحدة',employee.address_building)}${profileDatum('صندوق البريد',employee.address_po_box)}</div></section>`;
    const emergency=canSeeEmergency?`<section class="profile-panel" data-profile-panel="emergency"><div class="section-head"><div><span class="eyebrow">${tr('اتصال آمن')}</span><h2>${tr('جهات اتصال الطوارئ')}</h2><p>${tr('تظهر فقط للموظف نفسه وللمخولين بإدارة جهات الطوارئ.')}</p></div>${hasPermission('employee.emergency.manage')?`<button class="primary" data-add-emergency="${employee.id}">${icon('plus')}${tr('إضافة جهة اتصال')}</button>`:''}</div><div class="emergency-contact-list loading-block" data-emergency-list="${employee.id}">${tr('جارٍ تحميل جهات الاتصال…')}</div></section>`:'';
    const custody=canSeeCustody?`<section class="profile-panel" data-profile-panel="custody"><div class="section-head"><div><span class="eyebrow">${tr('الأصول المسلّمة')}</span><h2>${tr('العهد والأصول')}</h2><p>${tr('سجل استلام وتسليم العهدة مع الرقم التسلسلي وحالة الأصل.')}</p></div>${hasPermission('employee_custody.manage')?`<button class="primary" data-add-custody="${employee.id}">${icon('plus')}${tr('إضافة عهدة')}</button>`:''}</div><div class="custody-list loading-block" data-custody-list="${employee.id}">${tr('جارٍ تحميل سجل العهد…')}</div></section>`:'';
