  function custodyPrintMarkup(c,organization,printType){const isReturn=printType==='return',title=isReturn?'سجل تسليم عهدة / Custody Return Record':'سجل استلام عهدة / Custody Receipt Record',photos=isReturn?(c.return_photos||[]):(c.received_photos||[]);return `<article class="custody-print" id="custodyPrint"><header><div class="brand"><span class="brand-mark">${organization.logo_data?`<img src="${esc(organization.logo_data)}" alt="${tr('شعار المؤسسة')}">`:'م'}</span><div><b>${esc(organization.display_name||'خيشة - Khaisha')}</b><small>${esc(organization.legal_name||'إدارة الموارد البشرية')}</small></div></div><span dir="ltr">${esc(c.serial_number||'—')}</span></header><div class="custody-print-title"><span class="eyebrow">${isReturn?'RETURN / تسليم':'RECEIPT / استلام'}</span><h1>${title}</h1><p>${tr('وثيقة داخلية محفوظة ضمن ملف الموظف')}</p></div><section class="custody-print-facts"><div><small>${tr('الموظف')}</small><b>${esc(c.employee_name||'—')}</b></div><div><small>${tr('الرقم الوظيفي')}</small><b dir="ltr">${esc(c.employee_no||'—')}</b></div><div><small>${tr('العهدة')}</small><b>${esc(c.asset_name||'—')}</b></div><div><small>${tr('النوع / الموديل')}</small><b>${esc(c.asset_type||'—')}</b></div><div><small>${tr('الرقم التسلسلي')}</small><b dir="ltr">${esc(c.serial_number||'—')}</b></div><div><small>${tr('تاريخ الاستلام')}</small><b>${dateText(c.received_on)}</b></div><div><small>${tr('حالة الاستلام')}</small><b>${custodyConditionLabel(c.received_condition)}</b></div>${isReturn?`<div><small>${tr('تاريخ التسليم')}</small><b>${dateText(c.returned_on)}</b></div><div><small>${tr('حالة التسليم')}</small><b>${esc(c.return_condition||'—')}</b></div>`:''}</section>${photos.length?`<section class="custody-print-photos"><b>${tr(isReturn?'صور التسليم':'صور الاستلام')}</b><div>${photos.map(photo=>`<img src="${esc(photo.data_url)}" alt="${esc(photo.caption||photo.file_name)}">`).join('')}</div></section>`:''}${c.notes?`<p class="custody-print-notes"><b>${tr('ملاحظات')}:</b> ${esc(c.notes)}</p>`:''}<footer><div><b>${tr('توقيع الموظف')}</b><span></span></div><div><b>${tr('مسؤول الموارد البشرية')}</b><span></span></div><div><b>${tr('التاريخ')}</b><span>${dateText(isReturn?c.returned_on:c.received_on)}</span></div></footer></article><div class="card-actions"><button class="primary" data-print-custody-final>${tr('طباعة السجل')}</button><button class="secondary" data-close-modal>${tr('إغلاق')}</button></div>`}
  async function printCustody(id,printType='receipt'){try{const response=await api(`/api/employee-custody/${id}/print`,{method:'POST',body:{print_type:printType}}),c=response.custody||response,organization=response.organization||state.org||{};openModal(printType==='return'?'تسليم عهدة':'استلام عهدة',custodyPrintMarkup(c,organization,printType),true)}catch(error){alertMessage(apiError(error),true)}}
  async function saveCustody(form){const button=$('button[type=submit]',form);setBusy(button,true);try{const body={asset_name:form.asset_name.value,asset_type:form.asset_type.value,serial_number:form.serial_number.value,received_on:form.received_on.value,received_condition:form.received_condition.value,returned_on:form.returned_on.value||null,return_condition:form.return_condition.value,notes:form.notes.value},receivedPhotos=await custodyPhotoPayload(form.received_photos),returnPhotos=await custodyPhotoPayload(form.return_photos),id=form.custody_id.value,employeeId=form.employee_id.value;if(receivedPhotos.length)body.received_photos=receivedPhotos;if(returnPhotos.length)body.return_photos=returnPhotos;await api(id?`/api/employee-custody/${id}`:`/api/employees/${employeeId}/custody`,{method:id?'PATCH':'POST',body});closeModal();toast(id?'تم تحديث سجل العهدة':'تمت إضافة العهدة إلى ملف الموظف');await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
