    const emergency=canEmergency?panel('emergency','جهات اتصال الطوارئ',`<div class="profile-editor-emergency-head"><p>${tr('جهات اتصال متعددة محفوظة كسجلات مستقلة وآمنة.')}</p><button type="button" class="primary" data-add-emergency="${employee.id}">${icon('plus')}${tr('إضافة جهة اتصال')}</button></div><div class="emergency-contact-list loading-block" data-emergency-list="${employee.id}">${tr('جارٍ تحميل جهات الاتصال…')}</div>`):'';
