    const employmentPanel=$('[data-profile-editor-panel="employment"]',$('#modalBody'));if(employmentPanel){employmentPanel.querySelector('input[name="salary"]')?.closest('label')?.remove();employmentPanel.insertAdjacentHTML('beforeend',contractFieldsMarkup(employee));if(hasPermission('salary.view'))employmentPanel.insertAdjacentHTML('beforeend',salaryFieldsMarkup(employee))}
    prepareEmployeePhotoAndAge($('#employeeProfileForm'),employee.photo_data||'');
