  async function saveEmployeeProfile(form){const button=$('button[type="submit"]',form),employeeId=form.employee_id.value;setBusy(button,true);try{const body=employeeProfilePayload(form),photo=await fileData(form.photo.files[0]);if(photo)body.photo_data=photo;await api(`/api/employees/${employeeId}`,{method:'PATCH',body});closeModal();toast('تم تحديث ملف الموظف وحساب العمر والاكتمال');await loadEmployees();await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
  function emergencyPhoneIsValid(value){return !value||/^[+0-9() ./-]{5,60}$/.test(value)}
  function validateEmergencyPhoneInput(input,showMessage=false){if(!input)return true;const value=input.value.trim(),valid=emergencyPhoneIsValid(value),message=tr('رقم الهاتف غير صالح. استخدم الأرقام الإنجليزية فقط مع + أو المسافات أو الشرطات.');input.setCustomValidity(valid?'':message);const error=input.parentElement?.querySelector('.field-error');if(error){error.textContent=message;error.hidden=valid||!showMessage}input.classList.toggle('invalid',!valid&&showMessage);return valid}
  function emergencyContactModal(employeeId,contact={}){const editing=Boolean(contact.id);openModal(editing?'تعديل جهة اتصال الطوارئ':'إضافة جهة اتصال للطوارئ',`<form id="emergencyContactForm"><input name="employee_id" type="hidden" value="${employeeId}"><input name="contact_id" type="hidden" value="${contact.id||''}"><div class="form-grid"><label>${tr('الاسم الكامل')}<input name="full_name" required maxlength="180" value="${esc(contact.full_name||'')}"></label><label>${tr('صلة القرابة')}<input name="relationship" required maxlength="100" value="${esc(contact.relationship||'')}"></label><label>${tr('رقم الهاتف')}<input name="phone" required dir="ltr" inputmode="tel" pattern="[+0-9() ./-]{5,60}" title="${tr('رقم الهاتف غير صالح. استخدم الأرقام الإنجليزية فقط مع + أو المسافات أو الشرطات.') }" aria-describedby="emergencyPhoneError" data-emergency-phone maxlength="60" value="${esc(contact.phone||'')}"><small id="emergencyPhoneError" class="field-error" role="alert" hidden></small></label><label>${tr('رقم بديل')}<input name="alternate_phone" dir="ltr" inputmode="tel" pattern="[+0-9() ./-]{5,60}" title="${tr('رقم الهاتف غير صالح. استخدم الأرقام الإنجليزية فقط مع + أو المسافات أو الشرطات.') }" aria-describedby="emergencyAlternatePhoneError" data-emergency-phone maxlength="60" value="${esc(contact.alternate_phone||'')}"><small id="emergencyAlternatePhoneError" class="field-error" role="alert" hidden></small></label><label>${tr('البريد الإلكتروني')}<input name="email" type="email" dir="ltr" maxlength="254" value="${esc(contact.email||'')}"></label><label class="check-row"><input name="is_primary" type="checkbox" ${contact.is_primary?'checked':''}> ${tr('جهة الاتصال الرئيسية')}</label><label class="span-2">${tr('ملاحظات')}<textarea name="notes" rows="3" maxlength="800">${esc(contact.notes||'')}</textarea></label></div><div class="button-row"><button class="primary" type="submit">${tr(editing?'حفظ التعديلات':'إضافة جهة الاتصال')}</button><button class="secondary" type="button" data-close-modal>${tr('إلغاء')}</button></div></form>`,true);$$('[data-emergency-phone]',$('#emergencyContactForm')).forEach(input=>validateEmergencyPhoneInput(input));}
  async function saveEmergencyContact(form){const employeeId=form.employee_id.value,contactId=form.contact_id.value,button=$('button[type="submit"]',form),valid=[...$$('[data-emergency-phone]',form)].every(input=>validateEmergencyPhoneInput(input,true));if(!valid){form.querySelector('[data-emergency-phone].invalid')?.focus();return}const body={full_name:form.full_name.value,relationship:form.relationship.value,phone:form.phone.value,alternate_phone:form.alternate_phone.value,email:form.email.value,is_primary:form.is_primary.checked,notes:form.notes.value};setBusy(button,true);try{await api(contactId?`/api/emergency-contacts/${contactId}`:`/api/employees/${employeeId}/emergency-contacts`,{method:contactId?'PATCH':'POST',body});closeModal();toast(contactId?'تم تحديث جهة اتصال الطوارئ':'تمت إضافة جهة اتصال الطوارئ');await openEmployee(employeeId);$(`[data-profile-tab="emergency"]`,$('#modalBody'))?.click()}catch(error){const field=error.details?.field;if(field)validateEmergencyPhoneInput(form.elements[field],true);alertMessage(apiError(error),true);setBusy(button,false)}}
  function documentOptions(selected=''){return documentTypes.map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${tr(label)}</option>`).join('')}
  function documentTypeLabel(type){return tr(documentTypes.find(x=>x[0]===type)?.[1]||type)}
  function documentStatusLabel(d){if(d.status==='valid')return tr('سارية');if(d.status==='expiring_soon')return tr('تنتهي خلال {days} يوم',{days:digits(d.days_remaining)});if(d.status==='expired')return tr('منتهية منذ {days} يوم',{days:digits(Math.abs(d.days_remaining||0))});if(d.status==='no_expiry')return tr('بلا انتهاء');if(d.status==='archived')return tr('أرشيفية');return tr(d.status)}
  function documentStatusClass(status){return status==='expired'?'red':status==='expiring_soon'?'warn':status==='archived'?'neutral':''}
  function cardOrganizationMark(card,light=false){const o=card.organization||{};return `<div class="brand employee-card-brand ${light?'brand-light':''}"><span class="brand-mark">${o.logo_data?`<img src="${esc(o.logo_data)}" alt="${tr('شعار المؤسسة')}">`:esc(initials(o.display_name||'م'))}</span><span><b data-i18n-preserve>${esc(o.display_name||'خيشة - Khaisha')}</b><small>${tr('بطاقة موظف مؤسسية')}</small></span></div>`}
  function cardPhoto(employee){return employee.photo_data?`<img class="employee-card-photo card-photo" src="${esc(employee.photo_data)}" alt="${tr('صورة الموظف')}">`:`<span class="employee-card-photo card-photo initials" aria-label="${tr('لا توجد صورة؛ الأحرف الأولى')}">${esc(initials(employee.full_name))}</span>`}
  function cardFacesMarkup(card,id=''){
    const e=card.employee||{},d=card.design||{},template=d.template||'portrait_orbit',style=`--card-primary:${esc(d.primary_color||'#123d34')};--card-accent:${esc(d.accent_color||'#c6a15b')}`;
    const validUntil=card.valid_until?dateText(card.valid_until):'—',validFrom=card.valid_from?dateText(card.valid_from):'';
    return `<div class="employee-card-spread template-${template}" ${id?`id="${id}"`:''} data-card-template="${template}" style="${style}"><article class="employee-id-card card-face front" data-card-face="front" aria-label="${tr('الوجه الأمامي للبطاقة')}">${cardOrganizationMark(card,true)}<div class="card-geometry" aria-hidden="true"></div><div class="card-person">${cardPhoto(e)}<div class="card-person-copy"><span class="card-kicker">${tr('بطاقة موظف')}</span><h2 data-i18n-preserve>${esc(e.full_name||'—')}</h2><p data-i18n-preserve>${esc(e.job_title||'—')}</p><dl><div><dt>${tr('الرقم الوظيفي')}</dt><dd>${esc(e.employee_no||'—')}</dd></div><div><dt>${tr('القسم')}</dt><dd data-i18n-preserve>${esc(e.department_name||'—')}</dd></div><div><dt>${tr('الدرجة')}</dt><dd data-i18n-preserve>${esc(e.job_grade||'—')}</dd></div></dl></div></div><div class="card-languages"><small>${tr('اللغات')}</small>${languageBadges(card.languages||e.languages||[],template==='executive_horizontal')}</div><footer><span>${validFrom?tr('من {from} حتى {to}',{from:validFrom,to:validUntil}):tr('صالحة حتى {date}',{date:validUntil})}</span><b>${esc(card.verification_reference||'')}</b></footer></article><article class="employee-id-card card-face back" data-card-face="back" aria-label="${tr('الوجه الخلفي للبطاقة')}">${cardOrganizationMark(card,true)}<div class="card-back-body"><span class="card-kicker">${tr('العناية بالبطاقة')}</span><h2>${tr('تعليمات مهمة')}</h2><p data-i18n-preserve>${esc(d.back_instructions||tr('البطاقة شخصية ولا يجوز استخدامها من غير صاحبها. عند العثور عليها يرجى التواصل مع المؤسسة.'))}</p><address><span><b>${tr('الهاتف')}</b>${esc(d.contact_phone||tr('غير محدد'))}</span><span><b>${tr('البريد الإلكتروني')}</b>${esc(d.contact_email||tr('غير محدد'))}</span></address><div class="verification-zone"><small>${tr('تحقق داخلي')}</small><b>${esc(card.verification_reference||'—')}</b><span>${esc(card.verification_path||'')}</span></div></div><footer><span class="status ${statusClass(card.status)}">${esc(tr(card.status_label||'—'))}</span><span>${card.valid_until?tr('الصلاحية {date}',{date:validUntil}):esc(tr(card.reason||''))}</span></footer></article></div>`
  }
  function workCardMarkup(card){const e=card.employee||{},disabled=card.can_print?'':'disabled',validity=card.valid_from&&card.valid_until?tr('من {from} حتى {to}',{from:dateText(card.valid_from),to:dateText(card.valid_until)}):card.valid_until?tr('حتى {date}',{date:dateText(card.valid_until)}):tr(card.reason||'');return `<div class="card-validity ${card.status}"><b>${esc(tr(card.status_label||'—'))}</b><span>${validity}</span></div><div class="employee-card-viewport" data-card-fit-stage>${cardFacesMarkup(card,'workCardPrint')}</div><div class="card-actions card-print-actions"><button class="primary" data-print-card="${e.id}" data-card-print-face="both" ${disabled}>${tr('طباعة الوجهين')}</button><button class="secondary" data-print-card="${e.id}" data-card-print-face="front" ${disabled}>${tr('طباعة الأمام')}</button><button class="secondary" data-print-card="${e.id}" data-card-print-face="back" ${disabled}>${tr('طباعة الخلف')}</button>${hasPermission('org.manage')?`<button class="text-btn" data-card-settings>${tr('تبديل القالب')}</button>`:''}${card.can_print?'':`<span class="status red card-disabled-reason">${esc(tr(card.reason))}</span>`}</div>`}
  async function showWorkCard(employeeId){try{const path=String(employeeId)===String(state.user?.employee_id)?'/api/me/card':'/api/employees/'+employeeId+'/card',response=await api(path),card=response.card||response;openModal('البطاقة الوظيفية',workCardMarkup(card),true)}catch(error){alertMessage(apiError(error),true)}}
  async function salaryCertificate(employeeId){openModal(tr('إصدار شهادة راتب'),`<form id="certificateForm"><label>${tr('الغرض من الشهادة')}<input name="purpose" required value="${tr('إلى من يهمه الأمر')}"></label><input type="hidden" name="employee_id" value="${employeeId}"><button class="primary" type="submit">${tr('إنشاء الشهادة')}</button></form>`)}
  function salaryCertificateRequestModal(){openModal('طلب شهادة راتب',`<form id="certificateRequestForm"><div class="security-callout">سيتم إرسال الطلب إلى الموارد البشرية. لا تظهر لك تفاصيل الراتب ضمن الطلب.</div><label>الجهة المستلمة للشهادة<input name="purpose" required maxlength="500" placeholder="مثال: سفارة دولة الإمارات" autofocus></label><div class="button-row"><button class="primary" type="submit">إرسال الطلب</button><button class="secondary" type="button" data-close-modal>إلغاء</button></div></form>`)}
  async function requestSalaryCertificate(form){const button=$('button[type=submit]',form);setBusy(button,true,'جارٍ الإرسال…');try{await api('/api/salary-certificates/request',{method:'POST',body:{purpose:form.purpose.value}});closeModal();toast('تم إرسال طلب شهادة الراتب إلى الموارد البشرية');}catch(error){alertMessage(apiError(error),true)}finally{setBusy(button,false)}}
  function salaryCertificateStatus(value){return ({requested:'قيد مراجعة الموارد البشرية',approved:'معتمد وتم إرساله للبريد',rejected:'مرفوض',issued:'صادر'})[value]||value||'—'}
  function certificateRequestRows(list,privileged){return list.length?list.map(item=>`<div class="list-item certificate-request-row"><div><span class="status ${statusClass(item.request_status)}">${esc(salaryCertificateStatus(item.request_status))}</span><h3>${esc(privileged?(item.employee_name||'—'):'طلب شهادة راتب')}</h3><p>${esc(item.purpose||'—')}</p><small>${privileged?`${esc(item.employee_no||'—')} · ${money(item.salary||0)} · `:''}${item.requested_at?dateTimeText(item.requested_at):''}${item.requester_name?` · ${esc(item.requester_name)}`:''}${privileged&&item.request_status==='approved'&&item.email_status?` · ${item.email_status==='sent'?'أُرسل البريد':item.email_status==='queued'?'محفوظ للإرسال':'تعذر الإرسال'}`:''}</small></div>${privileged&&item.request_status==='requested'?`<div class="button-row"><button class="primary" data-certificate-decision="approve" data-certificate-id="${item.id}" data-certificate-employee="${esc(item.employee_name||'')}" data-certificate-purpose="${esc(item.purpose||'')}" data-certificate-salary="${esc(item.salary||0)}">مراجعة واعتماد PDF</button><button class="danger" data-certificate-decision="reject" data-certificate-id="${item.id}" data-certificate-employee="${esc(item.employee_name||'')}" data-certificate-purpose="${esc(item.purpose||'')}">رفض</button></div>`:''}${item.decision_note?`<small class="certificate-decision-note">${esc(item.decision_note)}</small>`:''}</div>`).join(''):'<div class="empty">لا توجد طلبات شهادة راتب.</div>'}
  async function loadSalaryCertificateWorkspace(){const requests=await api('/api/salary-certificates/requests');const requestList=items(requests);const pending=$('#salaryCertificateRequestsList');if(pending)pending.innerHTML=certificateRequestRows(requestList,hasPermission('salary_certificate.issue'));if(hasPermission('salary_certificate.verify')){const history=await api('/api/salary-certificates/history');const historyRoot=$('#salaryCertificateHistoryList');if(historyRoot){const rows=items(history);historyRoot.innerHTML=rows.length?rows.map(item=>`<div class="list-item"><div><b dir="ltr">${esc(item.certificate_no||'—')}</b><p>${esc(item.employee_name||item.employee?.name||item.employee?.full_name||'—')} · ${esc(item.purpose||'—')}</p><small dir="ltr">${esc(item.verification_code||'—')}</small><small>${esc(salaryCertificateStatus(item.request_status||'issued'))} · ${dateTimeText(item.issued_at)}</small></div><span class="status ${statusClass(item.verification_status)}">${item.verification_status==='valid'?'سجل محفوظ':'ملغاة'}</span></div>`).join(''):'<div class="empty">لا يوجد سجل إصدار حتى الآن.</div>'}}}
  function certificateDecisionModal(id,action,details={}){const approve=action==='approve';openModal(approve?'مراجعة واعتماد شهادة الراتب':'رفض طلب شهادة الراتب',`<form id="certificateDecisionForm"><input type="hidden" name="certificate_id" value="${esc(id)}"><input type="hidden" name="decision_action" value="${esc(action)}"><div class="certificate-review-summary"><b>${esc(details.employee||'الموظف')}</b><span>${esc(details.purpose||'—')}</span>${approve?`<strong>${money(details.salary||0)}</strong>`:''}</div><p>${approve?'سيتم تثبيت بيانات الموظف والراتب وقت الاعتماد، وإنشاء رقم إصدار ورمز تحقق وتوليد PDF وإرساله إلى البريد المؤسسي.':'سيتم حفظ قرار الرفض ضمن السجل غير القابل للحذف.'}</p><label>${approve?'ملاحظة الاعتماد (اختياري)':'سبب الرفض'}<textarea name="decision_note" rows="4" ${approve?'':'required'}></textarea></label><div class="button-row"><button class="primary" type="submit">${approve?'اعتماد وإرسال':'تأكيد الرفض'}</button><button class="secondary" type="button" data-close-modal>إلغاء</button></div></form>`)}
  async function decideSalaryCertificate(form){const button=$('button[type=submit]',form);setBusy(button,true,'جارٍ المعالجة…');try{const result=await api(`/api/salary-certificates/${formControl(form,'certificate_id').value}/decision`,{method:'POST',body:{action:formControl(form,'decision_action').value,decision_note:formControl(form,'decision_note').value}});closeModal();toast(result.request?.email_status==='sent'?'تم الاعتماد وإرسال PDF بالبريد':'تم حفظ القرار؛ سيُرسل PDF عند توفر SMTP');await loadSalaryCertificateWorkspace()}catch(error){alertMessage(apiError(error),true)}finally{setBusy(button,false)}}
  async function createCertificate(form){const button=$('button[type=submit]',form);setBusy(button,true,'جارٍ الإصدار…');try{const created=await api('/api/salary-certificates',{method:'POST',body:{employee_id:Number(form.employee_id.value)||form.employee_id.value,purpose:form.purpose.value}});const cert=created.certificate||created;renderCertificate(cert);setBusy(button,false)}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
  function renderCertificateLegacy(data){
    const c=data.certificate||data,e=c.employee||{},o=c.organization||state.org||{};
    const issueNumber=esc(c.certificate_no||c.reference_number||c.reference||c.id);
    const purpose=esc(c.purpose||tr('إلى من يهمه الأمر'));
    const organization=esc(o.legal_name||o.display_name||tr('المؤسسة'));
    openModal('شهادة راتب',`<article class="certificate" id="certificatePrint"><header class="certificate-head"><div class="brand"><span class="brand-mark">${o.logo_data?`<img src="${esc(o.logo_data)}" alt="${tr('شعار المؤسسة')}">`:'م'}</span><span data-i18n-preserve><b>${esc(o.display_name||'خيشة - Khaisha')}</b><small>${esc(o.legal_name||'')}</small></span></div><small>${tr('رقم الإصدار: {number}',{number:issueNumber})}<br>${dateText((c.issued_at||c.issued_date||c.created_at||'').slice(0,10))}</small></header><h1>${tr('شهادة راتب')}</h1><div class="certificate-body"><p>${tr('السادة/ {purpose} المحترمون،',{purpose:`<b>${purpose}</b>`})}</p><p>${tr('تشهد {organization} بأن الموظف الموضحة بياناته يعمل لديها حتى تاريخ إصدار هذه الشهادة.',{organization})}</p><div class="certificate-data"><div><small>${tr('اسم الموظف')}</small><b data-i18n-preserve>${esc(e.name||e.full_name||c.employee_name)}</b></div><div><small>${tr('الرقم الوظيفي')}</small><b>${esc(e.employee_no||e.employee_number||c.employee_number||'—')}</b></div><div><small>${tr('المسمى الوظيفي')}</small><b data-i18n-preserve>${esc(e.job_title||c.job_title||'—')}</b></div><div><small>${tr('الفرع')}</small><b data-i18n-preserve>${esc(e.branch_name||c.branch_name||'—')}</b></div><div><small>${tr('الدرجة الوظيفية')}</small><b data-i18n-preserve>${esc(e.job_grade||'—')}</b></div><div><small>${tr('إجمالي الراتب')}</small><b>${money(c.salary||e.salary)}</b></div></div><p>${tr('أصدرت هذه الشهادة بناءً على طلب الموظف دون أدنى مسؤولية على المؤسسة تجاه الغير.')}</p></div><section class="certificate-verification-seal"><div><span class="eyebrow">${tr('التحقق من الأصالة')}</span><b>${tr('امسح الباركود أو أدخل الرقم في نظام الموارد البشرية')}</b><small>${tr('بصمة الوثيقة')}: <span dir="ltr">${esc(c.document_fingerprint||'—')}</span></small></div>${code39Markup(c.verification_code||c.certificate_no)}</section><footer class="certificate-foot"><div><b>${tr('إدارة الموارد البشرية')}</b><small>${tr('التوقيع المعتمد')}</small></div><div class="certificate-stamp">${o.stamp_data?`<img src="${esc(o.stamp_data)}" alt="${tr('ختم المؤسسة')}">`:tr('ختم المؤسسة')}</div></footer></article><div class="card-actions"><button class="primary" data-print-certificate="${c.id}">${tr('طباعة / حفظ PDF')}</button><button class="secondary" data-close-modal>${tr('إغلاق')}</button></div>`,true)
  }
  function salaryCertificatePrintLabel(){return tr('طباعة الشهادة')}
  function certificateDate(value,locale){if(!value)return '—';try{return new Intl.DateTimeFormat(locale,{day:'2-digit',month:'long',year:'numeric'}).format(new Date(String(value).slice(0,10)+'T00:00:00'))}catch(_){return String(value)}}
  function certificateMoney(value,locale){return new Intl.NumberFormat(locale,{style:'currency',currency:'AED',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value)||0)}
  function renderCertificate(data){
    const c=data.certificate||data,e=c.employee||{},o=c.organization||state.org||{},issued=c.issued_at||c.issued_date||c.created_at||'',issueNumber=c.certificate_no||c.reference_number||c.reference||c.id,verification=c.verification_code||issueNumber,fingerprint=c.document_fingerprint||'—',employeeName=e.name||e.full_name||c.employee_name||'—',employeeNumber=e.employee_no||e.employee_number||c.employee_number||'—',jobTitle=e.job_title||c.job_title||'—',department=e.department_name||e.department||'—',grade=e.job_grade||e.job_grade_name||'—',branch=e.branch_name||c.branch_name||'—',hireDate=e.hire_date||'',salary=c.salary||e.salary,purpose=c.purpose||'إلى من يهمه الأمر';
    const arDate=certificateDate(issued,'ar-AE'),enDate=certificateDate(issued,'en-AE'),arSalary=certificateMoney(salary,'ar-AE'),enSalary=certificateMoney(salary,'en-AE'),breakdown=c.salary_breakdown||e.salary_breakdown||{},salaryLines=items(breakdown.lines).filter(line=>Number(line.amount)>0),salaryDetail=salaryLines.length?`<section class="salary-certificate-breakdown"><header><div><b>تفصيل الراتب الشهري</b><small>Monthly salary breakdown</small></div><strong>${esc(arSalary)}</strong></header><div>${salaryLines.map(line=>`<div><span>${esc(line.name)}<small dir="ltr">${esc(line.name_en||'')}</small></span><b>${esc(certificateMoney(line.amount,'ar-AE'))}</b></div>`).join('')}</div><footer><span>إجمالي البدلات <small>Total allowances</small><b>${esc(certificateMoney(breakdown.allowances_total||0,'ar-AE'))}</b></span><span>الإجمالي المعتمد <small>Approved total</small><b>${esc(arSalary)}</b></span></footer></section>`:'';
    openModal('شهادة راتب',`<article class="certificate salary-certificate" id="certificatePrint" data-i18n-preserve><header class="salary-certificate-letterhead"><div class="salary-certificate-org">${o.logo_data?`<img src="${esc(o.logo_data)}" alt="شعار المؤسسة">`:`<span>${esc(initials(o.display_name||'خ'))}</span>`}<div><b>${esc(o.display_name||'خيشة - Khaisha')}</b><small>${esc(o.legal_name||'')}</small></div></div><div class="salary-certificate-contact"><b>شهادة راتب | Salary Certificate</b><span>${esc(o.address||o.emirate||'United Arab Emirates')}</span><span dir="ltr">${esc([o.phone,o.email].filter(Boolean).join(' · '))}</span></div></header><section class="salary-certificate-meta"><div><small>رقم الإصدار<br>Issue No.</small><b dir="ltr">${esc(issueNumber)}</b></div><div><small>تاريخ الإصدار<br>Issue Date</small><b>${esc(arDate)}<br><span dir="ltr">${esc(enDate)}</span></b></div><div><small>الغرض<br>Purpose</small><b>${esc(purpose)}</b></div></section><div class="salary-certificate-language-grid"><section lang="ar" dir="rtl"><span class="certificate-language-mark">العربية</span><h1>شهادة راتب</h1><p>السادة/ <b>${esc(purpose)}</b> المحترمون،</p><p>تشهد <b>${esc(o.legal_name||o.display_name||'المؤسسة')}</b> بأن الموظف الموضحة بياناته أدناه يعمل لديها حتى تاريخ إصدار هذه الشهادة، وذلك وفق سجل الموارد البشرية المعتمد.</p></section><section lang="en" dir="ltr"><span class="certificate-language-mark">English</span><h1>Salary Certificate</h1><p>To: <b>${esc(purpose)}</b></p><p><b>${esc(o.legal_name||o.display_name||'The organization')}</b> hereby certifies that the employee whose details appear below is employed with the organization as of the issue date, according to the approved HR record.</p></section></div><section class="salary-certificate-facts" aria-label="Employee salary details"><div><span>اسم الموظف<br><i>Employee name</i></span><b>${esc(employeeName)}</b></div><div><span>الرقم الوظيفي<br><i>Employee number</i></span><b dir="ltr">${esc(employeeNumber)}</b></div><div><span>المسمى الوظيفي<br><i>Job title</i></span><b>${esc(jobTitle)}</b></div><div><span>القسم والفرع<br><i>Department & branch</i></span><b>${esc(department)} · ${esc(branch)}</b></div><div><span>الدرجة الوظيفية<br><i>Job grade</i></span><b>${esc(grade)}</b></div><div><span>تاريخ التعيين<br><i>Hire date</i></span><b>${esc(certificateDate(hireDate,'ar-AE'))}<br><i dir="ltr">${esc(certificateDate(hireDate,'en-AE'))}</i></b></div><div class="salary-certificate-total"><span>إجمالي الراتب الشهري<br><i>Total monthly salary</i></span><b>${esc(arSalary)}<br><i dir="ltr">${esc(enSalary)}</i></b></div></section><div class="salary-certificate-language-grid certificate-disclaimer"><p lang="ar" dir="rtl">أصدرت هذه الشهادة بناءً على طلب الموظف للغرض الموضح أعلاه، دون أدنى مسؤولية مالية أو قانونية على المؤسسة تجاه الغير.</p><p lang="en" dir="ltr">This certificate is issued at the employee's request for the stated purpose, without creating any financial or legal liability for the organization toward third parties.</p></div><section class="salary-certificate-authorization"><div><b>إدارة الموارد البشرية</b><span>Human Resources</span><i>التوقيع المعتمد / Authorized signature</i></div><div class="certificate-stamp">${o.stamp_data?`<img src="${esc(o.stamp_data)}" alt="ختم المؤسسة">`:`<span>ختم المؤسسة<br>Organization stamp</span>`}</div></section><section class="certificate-verification-seal salary-certificate-verification"><div><span class="eyebrow">التحقق من الأصالة · Authenticity verification</span><b>أدخل الرقم في صفحة التحقق بالنظام · Enter this code in the system verification page</b><small>البصمة · Fingerprint: <span dir="ltr">${esc(fingerprint)}</span></small></div>${code39Markup(verification)}</section><footer class="salary-certificate-footer"><span dir="ltr">${esc(issueNumber)}</span><span>خيشة HR · V5.7.0</span><span>وثيقة إلكترونية قابلة للتحقق · Verifiable electronic document</span></footer></article><div class="card-actions"><button class="primary" data-print-certificate="${c.id}" data-certificate-mode="detailed">${tr('طباعة تفصيلية')}</button><button class="secondary" data-print-certificate="${c.id}" data-certificate-mode="summary">${tr('طباعة إجمالي الراتب')}</button><button class="secondary" data-close-modal>${tr('إغلاق')}</button></div>`,true);if(salaryDetail){const facts=$('.salary-certificate-facts',$('#modalBody'));facts?.insertAdjacentHTML('afterend',salaryDetail)}
  }
  async function verifySalaryCertificate(form){const button=$('button[type="submit"]',form),result=$('#certificateVerificationResult'),code=form.code.value.trim().toUpperCase().replace(/\s+/g,'');form.code.value=code;setBusy(button,true,'جارٍ التحقق…');result.innerHTML='<div class="loading-block">جارٍ مطابقة الرقم والبصمة مع سجل الإصدار…</div>';try{const data=await api('/api/salary-certificates/verify',{method:'POST',body:{code}});renderSalaryVerification(data)}catch(error){result.innerHTML=`<div class="verification-state invalid"><span>×</span><div><h2>تعذر إتمام التحقق</h2><p>${esc(apiError(error))}</p></div></div>`}finally{setBusy(button,false)}}
  function renderSalaryVerification(data){const result=$('#certificateVerificationResult'),c=data.certificate,e=c?.employee||{},issuer=data.issuer||{},valid=Boolean(data.valid);if(!c){result.innerHTML=`<div class="verification-state invalid"><span>×</span><div><h2>رقم غير معتمد</h2><p>${esc(data.message)}</p><small>راجع الرقم المطبوع وأعد المحاولة. لا تعتمد الشهادة إذا استمرت هذه النتيجة.</small></div></div>`;return}result.innerHTML=`<div class="verification-state ${valid?'verified':'invalid'}"><span>${valid?'✓':'!'}</span><div><h2>${valid?'شهادة صحيحة':'شهادة غير صالحة للاعتماد'}</h2><p>${esc(data.message)}</p><small>تم التحقق في ${i18n()?.formatDate(data.verified_at,{dateStyle:'medium',timeStyle:'short'})}</small></div></div><div class="verification-record"><div><small>رقم التحقق</small><b dir="ltr">${esc(c.verification_code)}</b></div><div><small>رقم الإصدار</small><b dir="ltr">${esc(c.certificate_no)}</b></div><div><small>اسم الموظف</small><b>${esc(e.name||e.full_name||'—')}</b></div><div><small>الرقم الوظيفي</small><b>${esc(e.employee_no||'—')}</b></div><div><small>المسمى الوظيفي</small><b>${esc(e.job_title||'—')}</b></div><div><small>الراتب الصادر</small><b>${money(c.salary)}</b></div><div><small>تاريخ الإصدار</small><b>${dateText(String(c.issued_at||'').slice(0,10))}</b></div><div><small>أصدرها</small><b>${esc(issuer.name||'—')}</b></div><div><small>الغرض</small><b>${esc(c.purpose||'—')}</b></div><div><small>بصمة الوثيقة</small><b dir="ltr">${esc(c.document_fingerprint||'—')}</b></div></div><div class="verification-comparison"><b>طابق هذه البيانات مع النسخة المقدمة</b><p>أي اختلاف في الاسم أو الرقم أو الراتب أو تاريخ الإصدار يعني أن المستند المقدم لا يطابق الشهادة الأصلية.</p></div>`}

  async function uploadData(file,allowed,maxBytes=2*1024*1024){return new Promise((resolve,reject)=>{if(!file)return reject(new Error('اختر ملفاً أولاً.'));if(!allowed.includes(file.type))return reject(new Error('صيغة الملف غير مدعومة.'));if(file.size>maxBytes)return reject(new Error('حجم الملف يتجاوز الحد المسموح.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('تعذر قراءة الملف.'));reader.readAsDataURL(file)})}
  function documentModal(employeeId){openModal(tr('رفع وثيقة إلى ملف الموظف'),`<form id="employeeDocumentForm"><input type="hidden" name="employee_id" value="${employeeId}"><fieldset class="form-section"><legend>${tr('بيانات الوثيقة')}</legend><div class="form-grid"><label>${tr('نوع الوثيقة')}<select name="document_type">${documentOptions()}</select></label><label>${tr('الاسم أو العنوان')}<input name="title" required></label><label>${tr('رقم الوثيقة')}<input name="document_number"></label><label>${tr('جهة الإصدار')}<input name="issuer"></label><label>${tr('تاريخ الإصدار')}<input name="issued_on" type="date"></label><label>${tr('تاريخ الانتهاء')}<input name="expires_on" type="date"></label></div><label class="check-line"><input name="no_expiry" type="checkbox" data-no-expiry> ${tr('الوثيقة بلا تاريخ انتهاء')}</label><label>${tr('ملاحظات')}<textarea name="notes" rows="2"></textarea></label></fieldset><label class="upload-box">${tr('الملف')}<input name="file" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required><span>${tr('PDF أو PNG/JPEG/WebP حتى ٢ م.ب؛ تُرفض الملفات التنفيذية.')}</span></label><label class="check-line"><input name="visible_to_employee" type="checkbox" checked> ${tr('متاح للموظف في ملفه')}</label><div class="sticky-form-actions"><button class="primary" type="submit">${tr('رفع وحفظ الوثيقة')}</button></div></form>`,true)}
  async function saveEmployeeDocument(form){const button=$('button[type=submit]',form);setBusy(button,true,'جارٍ الرفع…');try{const file=form.file.files[0],dataUrl=await uploadData(file,['image/png','image/jpeg','image/webp','application/pdf']);await api(`/api/employees/${form.employee_id.value}/documents`,{method:'POST',body:{document_type:form.document_type.value,title:form.title.value,document_number:form.document_number.value,issuer:form.issuer.value,issued_on:form.issued_on.value||null,expires_on:form.expires_on.value||null,no_expiry:form.no_expiry.checked,file_name:file.name,data_url:dataUrl,notes:form.notes.value,visible_to_employee:form.visible_to_employee.checked}});const employeeId=form.employee_id.value;closeModal();toast('تم حفظ الوثيقة وتحديث حالة الصلاحية');await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
  async function viewDocument(id){try{const response=await api('/api/documents/'+id),d=response.document||response,isPdf=d.mime_type==='application/pdf';openModal(d.title,`<div class="document-detail"><div><span class="status ${documentStatusClass(d.status)}">${documentStatusLabel(d)}</span><dl><div><dt>${tr('النوع')}</dt><dd>${esc(documentTypeLabel(d.document_type))}</dd></div><div><dt>${tr('الرقم')}</dt><dd>${esc(d.document_number||'—')}</dd></div><div><dt>${tr('جهة الإصدار')}</dt><dd data-i18n-preserve>${esc(d.issuer||'—')}</dd></div><div><dt>${tr('الإصدار')}</dt><dd>${dateText(d.issued_on)}</dd></div><div><dt>${tr('الانتهاء')}</dt><dd>${d.no_expiry?tr('بلا انتهاء'):dateText(d.expires_on)}</dd></div></dl><p data-i18n-preserve>${esc(d.notes||'')}</p></div>${isPdf?`<iframe class="document-frame" src="${esc(d.data_url)}" title="${esc(d.title)}"></iframe>`:`<img class="document-preview" src="${esc(d.data_url)}" alt="${esc(d.title)}">`}</div><div class="card-actions"><a class="primary" href="${esc(d.data_url)}" download="${esc(d.file_name)}">${tr('تنزيل الملف')}</a>${isManager()?`<button class="secondary" data-edit-document="${d.id}">${tr('تعديل البيانات')}</button>${!d.archived?`<button class="secondary" data-archive-document="${d.id}">${tr('أرشفة')}</button>`:''}<button class="danger" data-delete-document="${d.id}">${tr('حذف')}</button>`:''}</div>`,true)}catch(error){alertMessage(apiError(error),true)}}
  async function editDocumentModal(id){try{const response=await api('/api/documents/'+id),d=response.document||response;openModal('تعديل بيانات الوثيقة',`<form id="documentEditForm"><input type="hidden" name="document_id" value="${d.id}"><input type="hidden" name="employee_id" value="${d.employee_id}"><div class="form-grid"><label>${tr('النوع')}<select name="document_type">${documentOptions(d.document_type)}</select></label><label>${tr('عنوان الوثيقة')}<input name="title" required value="${esc(d.title)}"></label><label>${tr('رقم الوثيقة')}<input name="document_number" value="${esc(d.document_number||'')}"></label><label>${tr('جهة الإصدار')}<input name="issuer" value="${esc(d.issuer||'')}"></label><label>${tr('تاريخ الإصدار')}<input name="issued_on" type="date" value="${esc(d.issued_on||'')}"></label><label>${tr('تاريخ الانتهاء')}<input name="expires_on" type="date" value="${esc(d.expires_on||'')}"></label></div><label class="check-line"><input name="no_expiry" type="checkbox" data-no-expiry ${d.no_expiry?'checked':''}> ${tr('بلا انتهاء')}</label><label>${tr('ملاحظات')}<textarea name="notes" rows="3">${esc(d.notes||'')}</textarea></label><label class="check-line"><input name="visible_to_employee" type="checkbox" ${d.visible_to_employee?'checked':''}> ${tr('متاح للموظف')}</label><button class="primary" type="submit">${tr('حفظ التعديلات')}</button></form>`)}catch(error){alertMessage(apiError(error),true)}}
  async function saveDocumentEdit(form){try{const employeeId=formControl(form,'employee_id').value,documentId=formControl(form,'document_id').value;await api('/api/documents/'+documentId,{method:'PATCH',body:{document_type:formControl(form,'document_type').value,title:formControl(form,'title').value,document_number:formControl(form,'document_number').value,issuer:formControl(form,'issuer').value,issued_on:formControl(form,'issued_on').value||null,expires_on:formControl(form,'expires_on').value||null,no_expiry:formControl(form,'no_expiry').checked,notes:formControl(form,'notes').value,visible_to_employee:formControl(form,'visible_to_employee').checked}});closeModal();toast('تم تحديث بيانات الوثيقة وتسجيلها في التدقيق');await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true)}}
  function employeeActionModal(employeeId){openModal('إضافة مخالفة أو تعهد',`<form id="employeeActionForm"><input type="hidden" name="employee_id" value="${employeeId}"><div class="form-grid"><label>النوع<select name="action_type"><option value="violation">مخالفة</option><option value="undertaking">تعهد</option></select></label><label>التاريخ<input name="action_date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label></div><label>الوصف<textarea name="description" rows="3" required></textarea></label><label>الجزاء أو الإجراء<input name="penalty"></label><label class="upload-box">مرفق اختياري<input name="file" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><span>PDF أو صورة حتى ٢ م.ب</span></label><button class="primary" type="submit">حفظ السجل</button></form>`)}
  async function saveEmployeeAction(form){const button=$('button[type=submit]',form);setBusy(button,true);try{const file=form.file.files[0],attachment=file?await uploadData(file,['image/png','image/jpeg','image/webp','application/pdf']):null;await api(`/api/employees/${form.employee_id.value}/actions`,{method:'POST',body:{action_type:form.action_type.value,action_date:form.action_date.value,description:form.description.value,penalty:form.penalty.value,attachment_data:attachment}});const employeeId=form.employee_id.value;closeModal();toast('تمت إضافة السجل وتحديث العداد');await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
  async function employeeReferenceModal(employeeId){if(!state.jobGrades.length||!state.jobTitles.length)await loadReferences(false);const employee=state.employees.find(e=>String(e.id)===String(employeeId))||{};openModal('تعديل الدرجة والمسمى',`<form id="employeeReferenceForm"><input type="hidden" name="employee_id" value="${employeeId}"><label>المسمى الوظيفي<select name="job_title_id" required>${state.jobTitles.filter(x=>x.active).map(x=>`<option value="${x.id}" ${String(x.id)===String(employee.job_title_id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>الدرجة الوظيفية<select name="job_grade_id" required>${state.jobGrades.filter(x=>x.active).map(x=>`<option value="${x.id}" ${String(x.id)===String(employee.job_grade_id)?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('')}</select></label><button class="primary" type="submit">حفظ وربط الملف</button></form>`)}
  async function saveEmployeeReference(form){try{const employeeId=form.employee_id.value;await api('/api/employees/'+employeeId,{method:'PATCH',body:{job_title_id:Number(form.job_title_id.value),job_grade_id:Number(form.job_grade_id.value)}});await loadEmployees();closeModal();toast('تم تحديث الدرجة والمسمى في الملف والوثائق');await openEmployee(employeeId)}catch(error){alertMessage(apiError(error),true)}}
