  async function loadBranches(){const data=await api('/api/branches');state.branches=items(data);renderBranches();setTimeout(renderBranchesMap,50)}
  function renderBranches(){const active=state.branches.filter(b=>b.active!==false).length,total=state.branches.reduce((s,b)=>s+Number(b.employee_count||0),0),mayManage=hasPermission('branch.manage');$('#branchMetrics').innerHTML=[['الفروع المسجلة',digits(state.branches.length),'محفوظة في قاعدة البيانات'],['نطاقات نشطة',digits(active),'تتحقق خادمياً'],['الموظفون المرتبطون',digits(total),'حسب التعيين الحالي']].map(metricHtml).join('');$('#branchCards').innerHTML=state.branches.length?state.branches.map(b=>`<article class="branch-card" data-branch-select="${b.id}"><div class="section-head"><div><h3>${esc(b.name)}</h3><p>${esc(b.address||'لا يوجد عنوان')}</p></div><span class="status ${b.active===false?'neutral':''}">${b.active===false?'متوقف':'نشط'}</span></div><footer><span>نطاق <b>${digits(b.radius_m)} م</b> · ${digits(b.employee_count||0)} موظف</span>${mayManage?`<span class="actions"><button class="text-btn" data-edit-branch="${b.id}">تعديل</button><button class="text-btn" data-delete-branch="${b.id}">حذف</button></span>`:''}</footer></article>`).join(''):'<div class="card empty">لا توجد فروع. أضف الفرع الأول وحدد نطاقه على الخريطة.</div>'}
  function mapAvailable(){return typeof window.L!=='undefined'}
  function clearMapFallback(container){container?.querySelector('.map-fallback')?.remove()}
  function settleMap(map,container,after){clearMapFallback(container);const refresh=()=>{if(!container?.isConnected)return;map.invalidateSize({pan:false});if(after)after()};requestAnimationFrame(()=>requestAnimationFrame(refresh));setTimeout(refresh,250)}
  function addMapTiles(map,container,onFailure){const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'});let loaded=false;const ready=()=>{loaded=true;container.dataset.mapState='ready';clearMapFallback(container)};tiles.once('load',ready);tiles.once('tileload',ready);tiles.on('tileerror',()=>{if(!loaded){container.dataset.mapState='tiles-unavailable';if(onFailure)onFailure()}});return tiles.addTo(map)}
  function renderBranchesMap(){const container=$('#branchesMap');if(!mapAvailable()){container.innerHTML='<div class="map-fallback">الخريطة غير متاحة حالياً. تبقى الإحداثيات اليدوية متاحة في نموذج الفرع.</div>';$('#mapStatus').textContent='إدخال يدوي';return}clearMapFallback(container);if(!state.map){state.map=L.map(container,{scrollWheelZoom:false,zoomAnimation:false}).setView([25.2048,55.2708],9);addMapTiles(state.map,container,()=>{$('#mapStatus').textContent='بلا اتصال · الإدخال اليدوي متاح'});$('#mapStatus').textContent='خريطة حية'}if(state.mapLayer)state.mapLayer.clearLayers();state.mapLayer=L.layerGroup().addTo(state.map);const bounds=[];state.branches.forEach(b=>{if(!Number.isFinite(Number(b.latitude))||!Number.isFinite(Number(b.longitude)))return;const ll=[Number(b.latitude),Number(b.longitude)];bounds.push(ll);L.circle(ll,{radius:Number(b.radius_m),color:b.active===false?'#69746d':'#1f6b58',weight:2,fillColor:'#1f6b58',fillOpacity:.16}).addTo(state.mapLayer).bindPopup(`<b>${esc(b.name)}</b><br>نطاق ${digits(b.radius_m)} متر`);L.marker(ll).addTo(state.mapLayer).bindPopup(`<b>${esc(b.name)}</b><br>${esc(b.address||'')}`)});settleMap(state.map,container,()=>{if(bounds.length)state.map.fitBounds(bounds,{padding:[40,40],maxZoom:13})})}
  function selectBranch(id){const b=state.branches.find(x=>String(x.id)===String(id));if(!b)return;$$('.branch-card').forEach(c=>c.classList.toggle('selected',c.dataset.branchSelect===String(id)));$('#branchGeoReadout').innerHTML=`<b>${esc(b.name)}</b> · المركز ${digits(Number(b.latitude).toFixed(6))}، ${digits(Number(b.longitude).toFixed(6))} · نصف القطر ${digits(b.radius_m)} متر`;if(state.map&&Number.isFinite(Number(b.latitude))){state.map.setView([Number(b.latitude),Number(b.longitude)],16)}}
  function branchModal(branch={}){const editing=Boolean(branch.id);openModal(editing?'تعديل الفرع والنطاق':'إضافة فرع وتحديد النطاق',`<form id="branchForm"><input type="hidden" name="branch_id" value="${esc(branch.id||'')}"><div class="form-grid"><label>${tr('اسم الفرع')}<input name="name" required value="${esc(branch.name||'')}"></label><label>${tr('العنوان')}<input name="address" required value="${esc(branch.address||'')}"></label><label>${tr('مدير الفرع')}<select name="manager_employee_id"><option value="">${tr('غير معين')}</option>${state.employees.map(e=>`<option value="${e.id}" ${String(e.id)===String(branch.manager_employee_id)?'selected':''}>${esc(e.name||e.full_name)}</option>`).join('')}</select></label><label>${tr('الحالة')}<select name="active"><option value="1" ${branch.active!==false?'selected':''}>${tr('نشط')}</option><option value="0" ${branch.active===false?'selected':''}>${tr('متوقف')}</option></select></label><label>${tr('خط العرض')}<input name="latitude" type="number" step="any" required value="${esc(branch.latitude??25.2048)}"></label><label>${tr('خط الطول')}<input name="longitude" type="number" step="any" required value="${esc(branch.longitude??55.2708)}"></label><label>${tr('نصف القطر بالمتر')}<input name="radius_m" type="range" min="50" max="5000" step="10" value="${esc(branch.radius_m||300)}"></label><label>${tr('القيمة الحالية')}<input id="radiusDisplay" value="${esc(branch.radius_m||300)} ${tr('متر')}" readonly></label></div><div class="live-radius" id="liveRadius">${tr('انقر على الخريطة لتحديد المركز، أو أدخل الإحداثيات يدوياً.')}</div><div id="branchModalMap" class="modal-map"><div class="map-fallback">${tr('تحميل الخريطة…')}</div></div><div class="button-row" style="margin-top:12px"><button type="button" class="secondary" id="useCurrentLocation">${tr('استخدام موقعي الحالي')}</button><button class="primary" type="submit">${tr(editing?'حفظ التعديلات':'إنشاء الفرع')}</button></div></form>`,true);setupBranchModalMap()}
  function setupBranchModalMap(){const form=$('#branchForm'),lat=form.latitude,lng=form.longitude,radius=form.radius_m,display=$('#radiusDisplay'),container=$('#branchModalMap');const update=()=>{display.value=digits(radius.value)+' '+tr('متر');$('#liveRadius').textContent=`${tr('المركز:')} ${Number(lat.value).toFixed(6)}، ${Number(lng.value).toFixed(6)} · ${tr('النطاق:')} ${radius.value} ${tr('متر')}`;if(state.modalMarker&&state.modalMap){const ll=[Number(lat.value),Number(lng.value)];state.modalMarker.setLatLng(ll);state.modalCircle.setLatLng(ll).setRadius(Number(radius.value));state.modalMap.panTo(ll)}};radius.addEventListener('input',update);lat.addEventListener('change',update);lng.addEventListener('change',update);$('#useCurrentLocation').addEventListener('click',()=>getPosition().then(p=>{lat.value=p.coords.latitude;lng.value=p.coords.longitude;update()}).catch(e=>alertMessage(e.message,true)));if(mapAvailable()){clearMapFallback(container);const center=[Number(lat.value),Number(lng.value)];state.modalMap=L.map(container,{scrollWheelZoom:false,zoomAnimation:false}).setView(center,15);addMapTiles(state.modalMap,container,()=>{$('#liveRadius').textContent+=' · '+tr('بلاطات الخريطة غير متاحة، والإحداثيات اليدوية تعمل')});state.modalCircle=L.circle(center,{radius:Number(radius.value),color:'#1f6b58',weight:3,fillColor:'#1f6b58',fillOpacity:.18}).addTo(state.modalMap).bringToFront();state.modalMarker=L.marker(center,{draggable:true}).addTo(state.modalMap);const set=ll=>{lat.value=ll.lat.toFixed(7);lng.value=ll.lng.toFixed(7);update()};state.modalMap.on('click',e=>set(e.latlng));state.modalMarker.on('dragend',e=>set(e.target.getLatLng()));settleMap(state.modalMap,container,()=>{state.modalMap.setView([Number(lat.value),Number(lng.value)],state.modalMap.getZoom(),{animate:false})})}else{container.innerHTML=`<div class="map-fallback">${tr('تعذر تحميل الخريطة. أدخل خط العرض والطول يدوياً أو استخدم موقعك الحالي.')}</div>`}update()}
  async function saveBranch(form){const button=$('button[type=submit]',form),branchId=formControl(form,'branch_id').value;setBusy(button,true);const body={name:formControl(form,'name').value.trim(),address:formControl(form,'address').value.trim(),manager_employee_id:formControl(form,'manager_employee_id').value||null,latitude:Number(formControl(form,'latitude').value),longitude:Number(formControl(form,'longitude').value),radius_m:Number(formControl(form,'radius_m').value),active:formControl(form,'active').value==='1'};try{await api(branchId?'/api/branches/'+branchId:'/api/branches',{method:branchId?'PATCH':'POST',body});closeModal();toast(branchId?'تم تحديث الفرع والنطاق':'تم إنشاء الفرع والنطاق الجغرافي');await loadBranches()}catch(error){alertMessage(apiError(error),true);setBusy(button,false)}}
