  async function exportAttendanceCsv(){const button=$('#exportAttendanceCsv');setBusy(button,true,'جارٍ التصدير…');try{const response=await fetch('/api/attendance/range.csv?'+attendanceQuery(),{credentials:'same-origin',headers:{Accept:'text/csv'}});if(!response.ok){let message='تعذر تصدير الكشف.';try{message=(await response.json()).error||message}catch(_){/* response is not JSON */}throw new Error(message)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a'),match=/filename="?([^";]+)"?/i.exec(response.headers.get('Content-Disposition')||'');link.href=url;link.download=match?.[1]||`attendance-${$('#attendanceFrom').value}-${$('#attendanceTo').value}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تصدير كشف الحضور بصيغة CSV')}catch(error){alertMessage(apiError(error),true)}finally{setBusy(button,false)}}
