  async function loadEvaluationCycle(cycleId){if(!cycleId)return;const detail=await api('/api/evaluation-cycles/'+cycleId);state.evaluationCycle=detail.cycle;renderCycleConsole()}
  function evaluationStageLabel(ev){if(!ev)return tr('لم تبدأ');if(ev.workflow_version<2)return statusLabel(ev.status);if(ev.status==='draft')return tr('مسودة الموظف');if(ev.status==='submitted')return tr('عند المسؤول المباشر');if(ev.status==='returned')return tr('معاد للمسؤول');if(ev.status==='in_review')return tr('مراجعة الموارد البشرية');if(ev.status==='approved'&&!ev.published)return tr('معتمد · بانتظار الإفصاح');if(ev.status==='approved'&&ev.published)return tr('منشور');return statusLabel(ev.status)}
