  async function openEvaluationRecord(id){try{state.evaluation=normalizeEvaluation(await api('/api/evaluations/'+id),state.pendingEvaluations.some(item=>String(item.id)===String(id)));await refreshEvaluationHistory();renderEvaluation()}catch(error){alertMessage(apiError(error),true)}}
  async function ensureEvaluation(){try{const own=state.evaluations.find(item=>String(item.employee_id)===String(state.user?.employee_id));if(own){await openEvaluationRecord(own.id);return}const response=await api('/api/evaluations',{method:'POST',body:{year:new Date().getFullYear()}});state.evaluation=normalizeEvaluation(response);state.evaluations.unshift(state.evaluation);toast('تم فتح التقييم المسند من الموارد البشرية');await refreshEvaluationHistory();renderEvaluation()}catch(error){alertMessage(apiError(error),true)}}
  function renderEvaluationAnnouncement(ev,own){const banner=$('#evaluationAnnouncement');if(!banner)return;banner.hidden=!Boolean(ev&&own&&ev.announced_at);if(banner.hidden){banner.innerHTML='';return}const due=cycleDueLabel(ev),late=!ev.submitted_at&&Number(daysUntil(ev.self_due_on))<0;banner.classList.toggle('late',late||ev.submitted_late);banner.innerHTML=`<div><span class="eyebrow">${esc(ev.announcement_title||tr('إعلان دورة الأداء'))}</span><h2 data-i18n-preserve>${esc(ev.cycle_name)}</h2><p data-i18n-preserve>${esc(ev.announcement_body||tr('أكمل تقييمك الذاتي ضمن الموعد المعتمد.'))}</p></div><div class="announcement-dates"><span><small>${tr('الفترة من')}</small><b>${tr('{start} إلى {end}',{start:dateText(ev.period_start),end:dateText(ev.period_end)})}</b></span><span><small>${tr('آخر موعد')}</small><b>${dateText(ev.self_due_on)}</b></span><strong class="countdown ${late?'late':''}">${esc(due)}</strong></div>`}
  function goalSelfFacts(goal){return `<div class="goal-self-facts"><span class="goal-type ${esc(goal.goal_type||'result')}">${esc(tr(goalTypeLabels[goal.goal_type]||goal.goal_type||'نتيجة / مؤشر'))}</span><span><small>${tr('الفترة')}</small>${dateText(goal.start_date)} — ${dateText(goal.end_date)}</span><span><small>${tr('الحالة')}</small>${esc(tr(progressLabels[goal.progress_status]||goal.progress_status||'—'))}</span><span><small>${tr('إنجاز الموظف')}</small>${digits(Number(goal.achievement||0).toFixed(0))}%</span></div><div class="goal-evidence"><small>${tr('الدليل / النتيجة')}</small><p data-i18n-preserve>${esc(goal.evidence_note||tr('لم يضف الموظف دليلاً بعد.'))}</p></div>`}
  function goalReady(goal){const achievement=Number(goal.achievement),consistent=goal.progress_status==='completed'?achievement===100:goal.progress_status==='not_completed'?achievement===0:goal.progress_status==='in_progress'?achievement>0&&achievement<100:false;return Boolean(goal.start_date&&goal.end_date&&goal.goal_type&&goal.progress_status&&String(goal.evidence_note||'').trim()&&consistent)}
  function evaluationQueueSelector(){const all=state.evaluations;if(!all.length)return'';return `<div class="evaluation-record-strip" aria-label="${tr('سجلات التقييم')}">${all.map(item=>`<button type="button" class="evaluation-record-chip ${String(item.id)===String(state.evaluation?.id)?'active':''}" data-evaluation-open="${item.id}"><span data-i18n-preserve>${esc(item.full_name||tr('موظف'))}</span><small>${esc(evaluationStageLabel(item))}</small>${item.can_manager_review||item.can_manager_override||item.can_hr_review||item.grievance_status==='submitted'?`<em>${tr('يتطلب إجراء')}</em>`:''}</button>`).join('')}</div>`}
  function evaluationGoalLibrary(ev,goals,editable){const used=new Set(goals.map(goal=>String(goal.source_template_id||''))),available=state.goalTemplates.filter(template=>template.active!==false&&!used.has(String(template.id)));return state.goalTemplates.length?`<section class="recommended-goals"><div class="recommended-goals-head"><div><span class="eyebrow" data-i18n-preserve>${esc(state.goalTemplateJobTitle?.name||tr('المسمى الوظيفي'))}</span><h3>${tr('مكتبة الأهداف المعتمدة')}</h3><p>${tr('اختر الأهداف قبل الإرسال. يحدد المسؤول النقاط في المرحلة التالية.')}</p></div>${editable&&available.length?`<button class="secondary" type="button" data-add-all-goal-templates>${tr('إضافة المتبقية')}</button>`:''}</div><div class="recommended-goal-grid">${state.goalTemplates.map(template=>{const selected=used.has(String(template.id));return `<article class="recommended-goal ${selected?'selected':''}"><div><span class="weight-badge small">${digits(template.default_weight)}%</span><h4 data-i18n-preserve>${esc(template.title)}</h4></div><p data-i18n-preserve>${esc(template.description)}</p><small data-i18n-preserve>${esc(template.measure)}</small>${selected?`<span class="status">${tr('مضاف')}</span>`:editable?`<button class="text-btn" type="button" data-add-goal-template="${template.id}">${tr('+ اختيار')}</button>`:''}</article>`}).join('')}</div></section>`:''}
  function publishedEvaluationHtml(ev,goals){const grievance=ev.grievance;return `<section class="evaluation-result"><div class="result-score"><span>النتيجة النهائية</span><strong>${digits(Number(ev.weighted_score||0).toFixed(1))}</strong><b>${esc(ev.rating||rating(ev.weighted_score))}</b><small>تم الإفصاح في ${dateText(ev.disclosure_date)}</small></div><div class="manager-report"><span class="eyebrow">تقرير المسؤول المباشر</span><p>${esc(ev.manager_report||'لم يسجل تقرير.')}</p></div></section><div class="evaluated-goals goal-review-ledger">${goals.map(goal=>`<article><div class="review-goal-copy"><b>${esc(goal.title)}</b><small>${esc(goal.measure||goal.description||'')}</small>${goalSelfFacts(goal)}</div><span><strong>${digits(Number(goal.awarded_points||0).toFixed(1))}</strong> / ${digits(goal.weight)}</span></article>`).join('')}</div>${grievance?`<div class="grievance-summary"><b>تظلم: ${esc(grievance.reason)}</b><p>${esc(grievance.note)}</p><span class="status ${statusClass(grievance.status)}">${esc(grievance.status==='submitted'?'قيد مراجعة HR':grievance.status==='amended'?'تم تعديل النتيجة':'تم رفض التظلم')}</span>${grievance.resolution_note?`<small>${esc(grievance.resolution_note)}</small>`:''}${hasPermission('evaluation.review')&&grievance.status==='submitted'?`<div class="button-row"><button class="secondary" type="button" data-resolve-grievance="reject">رفض مسبب</button><button class="primary" type="button" data-resolve-grievance="amend">تعديل النتيجة</button></div>`:''}</div>`:ev.can_grieve?'<button class="secondary" type="button" data-eval-grievance>تقديم تظلم واحد</button>':''}`}
  function renderTimeline(ev){const stages=[[tr('الموظف'),ev?.submitted_at,tr('إرسال الأهداف')],[tr('المسؤول المباشر'),ev?.manager_submitted_at,tr('النقاط والتقرير')],[tr('الموارد البشرية'),ev?.finalized_at,ev?.status==='returned'?tr('أعيد للمسؤول'):tr('المراجعة النهائية')],[tr('الإفصاح'),ev?.published?ev.disclosure_date:null,ev?.disclosure_date?dateText(ev.disclosure_date):tr('يحدده HR')]];$('#evaluationTimeline').innerHTML=ev?stages.map(([title,stamp,detail],index)=>`<div class="timeline-step ${stamp?'done':''} ${index===3?'final':''}"><b>${title}</b><small>${stamp?dateText(String(stamp).slice(0,10))+' · ':''}${esc(detail)}</small></div>`).join(''):`<div class="empty compact-empty">${tr('لا يوجد سجل محدد.')}</div>`}
  function renderEvaluation(){
    const ev=state.evaluation,goals=items(ev?.goals),own=Boolean(ev&&String(ev.employee_id)===String(state.user?.employee_id)),draft=Boolean(own&&ev.status==='draft'),reviewer=Boolean(ev&&!own),total=goals.reduce((sum,goal)=>sum+Number(goal.weight||0),0),ready=goals.length>0&&goals.every(goalReady);$('#evaluationWorkflowRibbon').innerHTML=evaluationWorkflowHtml(ev);$('#evaluationStatus').textContent=evaluationStageLabel(ev);$('#weightBadge').textContent=ev?.published?`${digits(Number(ev.weighted_score||0).toFixed(1))} / ١٠٠`:`${digits(total)} / ١٠٠`;$('#weightBadge').classList.toggle('invalid',draft&&(total!==100||!ready));$('#weightProgress').style.width=Math.min(total,100)+'%';renderEvaluationAnnouncement(ev,own);
    const privacy=$('#evaluationPrivacyGate');privacy.hidden=!Boolean(own&&ev&&!ev.published&&!draft);privacy.innerHTML=privacy.hidden?'':`<span>◉</span><div><b>${tr('النتيجة محجوبة حتى الإفصاح')}</b><p>${tr('لن تظهر نقاط الأهداف أو التقدير أو تقرير المسؤول قبل {date}.',{date:ev.disclosure_date?dateText(ev.disclosure_date):tr('اعتماد تاريخ الإفصاح')})}</p></div>`;
    $('#openEvaluation').hidden=!state.user?.employee_id||own;$('#evaluationEmployeeActions').hidden=!draft;$('#submitEvaluation').disabled=!draft||Math.abs(total-100)>.000001||!ready;$('#addGoal').disabled=!draft;$('#evaluationPanelTitle').textContent=reviewer?tr('ملف تقييم {name}',{name:ev?.full_name||''}):tr('دفتر أهدافي ونتائجي');$('#evaluationPanelHint').textContent=ev?`${ev.cycle_name||ev.year||''} · ${evaluationStageLabel(ev)}${ev.submitted_late?' · '+tr('إرسال متأخر'):''}`:tr('لا ينشئ الموظف دورة؛ تظهر هنا الدورة التي تعلنها الموارد البشرية.');
    let content=reviewer?evaluationQueueSelector():'';
    if(!ev)content+='<div class="empty">لا توجد دورة معلنة ومسندة إلى حسابك حالياً.</div>';
    else if(ev.published)content+=publishedEvaluationHtml(ev,goals);
    else if(ev.can_manager_review){content+=ev.can_manager_override?`<div class="security-callout evaluation-override-callout"><b>${tr('استكمال نيابة عن المسؤول المباشر')}</b><p>${tr('لم يتخذ المسؤول المباشر إجراءً. يمكنك إدخال نقاطه وتقريره بالنيابة عنه، ثم ينتقل التقييم مباشرة إلى مراجعة الموارد البشرية.')}</p></div>`:'';content+=ev.hr_comment?`<div class="return-note"><b>ملاحظة الموارد البشرية</b><p>${esc(ev.hr_comment)}</p></div>`:'';content+=`<form id="managerEvaluationForm" class="manager-score-form"><div class="evaluated-goals goal-review-ledger">${goals.map(goal=>`<article><div class="review-goal-copy"><div class="goal-title-row"><b>${esc(goal.title)}</b><span class="weight-badge small">${digits(goal.weight)}%</span></div><small>${esc(goal.measure||goal.description||'')}</small>${goalSelfFacts(goal)}</div><label>نقاط المسؤول<input name="goal_${goal.id}" data-manager-score="${goal.id}" type="number" min="0" max="${goal.weight}" step="0.01" value="${goal.awarded_points??''}" required><small>من ${digits(goal.weight)}</small></label></article>`).join('')}</div><div class="live-score"><span>مجموع نقاط المسؤول</span><strong id="managerScoreTotal">٠ / ١٠٠</strong></div><label>${ev.can_manager_override?tr('تقرير الاستكمال بالنيابة عن المسؤول'):tr('التقرير المهني للمسؤول المباشر')}<textarea name="manager_report" rows="6" required placeholder="${tr('قدّم تغذية راجعة عادلة ومحددة تربط النتائج بالسلوك والتطوير…')}">${esc(ev.manager_report||'')}</textarea></label><button class="primary" type="submit">${ev.can_manager_override?tr('استكمال وإرسال للموارد البشرية'):tr('إرسال النقاط والتقرير للموارد البشرية')}</button></form>`}
    else if(ev.can_hr_review){content+=`<div class="evaluated-goals goal-review-ledger">${goals.map(goal=>`<article><div class="review-goal-copy"><div class="goal-title-row"><b>${esc(goal.title)}</b><span class="weight-badge small">${digits(goal.weight)}%</span></div><small>${esc(goal.measure||goal.description||'')}</small>${goalSelfFacts(goal)}</div><span><strong>${digits(Number(goal.awarded_points||0).toFixed(1))}</strong> / ${digits(goal.weight)}</span></article>`).join('')}</div><div class="manager-report"><span class="eyebrow">تقرير المسؤول</span><p>${esc(ev.manager_report)}</p></div><div class="live-score"><span>المجموع المحتسب</span><strong>${digits(Number(ev.score_total||0).toFixed(1))} / ١٠٠</strong></div>`}
    else{if(draft)content+=evaluationGoalLibrary(ev,goals,draft);content+=goals.length?`<section class="recorded-goals performance-goal-ledger"><div class="section-head compact"><div><h3>${draft?'أهدافي وتقييمي الذاتي':'التقييم الذاتي المرسل'}</h3><p>${draft?'أكمل نوع الهدف وفترته وحالته ونسبة الإنجاز والدليل قبل الإرسال.':'تبقى نقاط المسؤول ونتيجته سرية حتى الإفصاح.'}</p></div><span class="status ${ready?'':'warn'}">${ready?'مكتمل للإرسال':'حقول ناقصة'}</span></div>${goals.map(goal=>`<article class="performance-goal-card ${goalReady(goal)?'ready':'needs-work'}"><header><div><span class="goal-type ${esc(goal.goal_type||'result')}">${esc(goalTypeLabels[goal.goal_type]||'نتيجة / مؤشر')}</span><h3>${esc(goal.title)}</h3><p>${esc(goal.measure||goal.description||'')}</p></div><span class="weight-badge">${digits(goal.weight)}%</span></header>${goalSelfFacts(goal)}${draft?`<footer><button class="secondary" type="button" data-edit-evaluation-goal="${goal.id}">تحرير التقييم الذاتي</button><button class="danger" type="button" data-delete-goal="${goal.id}">حذف</button></footer>`:''}</article>`).join('')}</section>`:'<div class="empty">اختر أهدافك أو اكتب هدفاً مخصصاً؛ لن يقبل الإرسال إلا عند اكتمال الحقول ومجموع ١٠٠.</div>'}
    $('#evaluationGoals').innerHTML=content;$('#evaluationApprovalActions').innerHTML=ev?.can_hr_review?'<div class="button-row vertical-actions"><button class="secondary" type="button" data-hr-review="return">إعادة للمسؤول</button><button class="primary" type="button" data-hr-review="approve">اعتماد وتحديد الإفصاح</button></div>':'';renderTimeline(ev);updateManagerScore()
  }
  function goalModal(goal={}){const ev=state.evaluation,start=goal.start_date||ev?.period_start||'',end=goal.end_date||ev?.period_end||'',editing=Boolean(goal.id);openModal(editing?'تحرير الهدف والتقييم الذاتي':'كتابة هدف مخصص',`<form id="goalForm"><input type="hidden" name="goal_id" value="${goal.id||''}"><div class="custom-goal-notice"><span class="icon-avatar">${icon('edit')}</span><p><b>${tr('هدف SMART قابل للقياس')}</b><br>${tr('اربط النتيجة بفترة واضحة، ثم سجّل حالتها ونسبة الإنجاز والدليل الفعلي.')}</p></div><div class="form-grid"><label>${tr('نوع الهدف')}<select name="goal_type" required>${Object.entries(goalTypeLabels).map(([value,label])=>`<option value="${value}" ${goal.goal_type===value?'selected':''}>${tr(label)}</option>`).join('')}</select></label><label>${tr('الوزن من ١٠٠')}<input name="weight" type="number" min="0.01" max="100" step="0.01" value="${goal.weight??''}" required></label></div><label>${tr('عنوان الهدف')}<input name="title" value="${esc(goal.title||'')}" required autofocus></label><label>${tr('الوصف')}<textarea name="description" rows="2">${esc(goal.description||'')}</textarea></label><label>${tr('مؤشر القياس / KPI')}<input name="measure" value="${esc(goal.measure||'')}" required></label><div class="form-grid"><label>${tr('بداية الهدف')}<input name="start_date" type="date" min="${ev?.period_start||''}" max="${ev?.period_end||''}" value="${start}" required></label><label>${tr('نهاية الهدف')}<input name="end_date" type="date" min="${ev?.period_start||''}" max="${ev?.period_end||''}" value="${end}" required></label></div><div class="form-grid"><label>${tr('حالة التقدم')}<select name="progress_status" required><option value="not_completed" ${!goal.progress_status||goal.progress_status==='not_completed'?'selected':''}>${tr('لم يُنجز')}</option><option value="in_progress" ${goal.progress_status==='in_progress'?'selected':''}>${tr('قيد التقدم')}</option><option value="completed" ${goal.progress_status==='completed'?'selected':''}>${tr('منجز')}</option></select></label><label>${tr('نسبة الإنجاز %')}<input name="achievement" type="number" min="0" max="100" step="1" value="${goal.achievement??0}" required></label></div><label>${tr('دليل الإنجاز / النتيجة')}<textarea name="evidence_note" rows="4" placeholder="${tr('مثال: خُفّض متوسط الإنجاز من ٣ أيام إلى يومين وفق تقرير العمليات.')}">${esc(goal.evidence_note||'')}</textarea><small>${tr('يمكن حفظ المسودة دون دليل، لكنه إلزامي عند اعتماد الإرسال.')}</small></label><label>${tr('ملاحظة إضافية للموظف')}<textarea name="employee_comment" rows="2">${esc(goal.employee_comment||'')}</textarea></label><button class="primary" type="submit">${tr(editing?'حفظ التحديث':'إضافة الهدف')}</button></form>`)}
  async function saveGoal(form){try{const body={title:formControl(form,'title').value,description:formControl(form,'description').value,weight:Number(formControl(form,'weight').value),measure:formControl(form,'measure').value,goal_type:formControl(form,'goal_type').value,start_date:formControl(form,'start_date').value,end_date:formControl(form,'end_date').value,progress_status:formControl(form,'progress_status').value,achievement:Number(formControl(form,'achievement').value),evidence_note:formControl(form,'evidence_note').value,employee_comment:formControl(form,'employee_comment').value},id=formControl(form,'goal_id').value;await api(id?`/api/evaluation-goals/${id}`:`/api/evaluations/${state.evaluation.id}/goals`,{method:id?'PATCH':'POST',body});closeModal();toast(id?'تم تحديث الهدف والتقييم الذاتي':'تم حفظ الهدف');await loadEvaluation()}catch(error){alertMessage(apiError(error),true)}}
  function evaluationCycleModal(cycle={}){const editing=Boolean(cycle.id),announced=cycle.status==='announced',year=cycle.year||new Date().getFullYear()+1,defaults={period_start:`${year}-01-01`,period_end:`${year}-12-31`,self_opens_on:`${year}-10-01`,self_due_on:`${year}-10-31`,manager_due_on:`${year}-11-15`,hr_due_on:`${year}-11-30`},v={...defaults,...cycle};if(announced){openModal('تمديد مواعيد الدورة',`<form id="evaluationCycleForm"><input type="hidden" name="cycle_id" value="${cycle.id}"><input type="hidden" name="mode" value="extend"><div class="evaluation-confidential"><b>الدورة معلنة</b><p>يمكن تمديد المواعيد فقط؛ لا يقبل النظام تقصير نافذة قائمة.</p></div><div class="form-grid"><label>آخر موعد للموظف<input name="self_due_on" type="date" min="${cycle.self_due_on}" value="${cycle.self_due_on}" required></label><label>موعد المسؤول<input name="manager_due_on" type="date" min="${cycle.manager_due_on}" value="${cycle.manager_due_on}" required></label><label>موعد HR<input name="hr_due_on" type="date" min="${cycle.hr_due_on}" value="${cycle.hr_due_on}" required></label></div><label>سبب التمديد<textarea name="reason" rows="3" required></textarea></label><div class="button-row"><button class="primary" type="submit">حفظ التمديد</button><button class="danger" type="button" data-close-evaluation-cycle="${cycle.id}">إغلاق الدورة</button></div></form>`);return}openModal(editing?'تعديل مسودة الدورة':'إنشاء دورة تقييم',`<form id="evaluationCycleForm"><input type="hidden" name="cycle_id" value="${cycle.id||''}"><input type="hidden" name="mode" value="draft"><div class="form-grid"><label>السنة<input name="year" type="number" min="2000" max="2200" value="${year}" required></label><label>اسم الدورة<input name="name" value="${esc(cycle.name||`تقييم الأداء ${year}`)}" required></label></div><div class="form-grid"><label>بداية فترة الأداء<input name="period_start" type="date" value="${v.period_start}" required></label><label>نهاية فترة الأداء<input name="period_end" type="date" value="${v.period_end}" required></label></div><div class="form-grid"><label>فتح التقييم الذاتي<input name="self_opens_on" type="date" value="${v.self_opens_on}" required></label><label>آخر موعد للموظف<input name="self_due_on" type="date" value="${v.self_due_on}" required></label><label>موعد المسؤول المباشر<input name="manager_due_on" type="date" value="${v.manager_due_on}" required></label><label>موعد المراجعة النهائية HR<input name="hr_due_on" type="date" value="${v.hr_due_on}" required></label></div><label>عنوان الإعلان<input name="announcement_title" value="${esc(cycle.announcement_title||`إعلان تقييم الأداء ${year}`)}" required></label><label>نص الإعلان<textarea name="announcement_body" rows="4" placeholder="سيضيف النظام الفترة والموعد إذا ترك فارغاً.">${esc(cycle.announcement_body||'')}</textarea></label><button class="primary" type="submit">${editing?'حفظ المسودة':'إنشاء ومعاينة النطاق'}</button></form>`)}
