  function orgPersonCard(person,nested=false){return `<article class="org-person-card${nested?' nested':''}" data-employee-id="${person.id}" tabindex="0"><span class="avatar">${person.photo_data?`<img src="${esc(person.photo_data)}" alt="">`:esc(initials(person.full_name))}</span><div><b>${esc(person.full_name)}</b><small>${esc(person.job_title||'—')} · ${esc(person.employee_no||'—')}</small><em>${esc(person.department_name||'دون قسم')} · ${esc(person.branch_name||'دون فرع')}</em></div>${person.direct_reports_count?`<span class="report-count">${digits(person.direct_reports_count)} تابع</span>`:''}</article>`}
  function renderOrgHierarchical(people){const ids=new Set(people.map(p=>String(p.id))),children=new Map();people.forEach(p=>{const key=p.manager_id&&ids.has(String(p.manager_id))?String(p.manager_id):'root';children.set(key,[...(children.get(key)||[]),p])});const branch=(person,seen=new Set())=>{if(seen.has(String(person.id)))return'';const next=new Set(seen).add(String(person.id)),reports=children.get(String(person.id))||[];return `<li>${orgPersonCard(person)}${reports.length?`<details class="org-report-group" open><summary>الفريق المباشر · ${digits(reports.length)} موظف</summary><ul>${reports.map(p=>branch(p,next)).join('')}</ul></details>`:''}</li>`};const roots=children.get('root')||[];return roots.length?`<div class="org-hierarchy-scroll"><ul class="org-hierarchy">${roots.map(p=>branch(p)).join('')}</ul></div>`:'<div class="empty">لا توجد نتائج تطابق عوامل التصفية.</div>'}
