  function renderExecutiveOrgGrid(data){const selectedDept=$('#orgDepartmentFilter').value,departments=items(data.departments).filter(d=>!selectedDept||String(d.id)===String(selectedDept));const gm=data.general_manager;return `<div class="org-fit-stage"><div class="executive-org-grid"><div class="gm-node"><span class="eyebrow">السلطة الأعلى · المدير العام</span>${gm?executivePersonCard(gm,gm.id):'<div class="empty">لم يربط ملف المدير العام بحساب نشط.</div>'}</div><div class="org-grid-connector" aria-hidden="true"></div><div class="department-columns">${departments.map(d=>{const members=items(d.employees),head=members.find(p=>Number(p.id)===Number(d.manager_employee_id)),staff=head?members.filter(p=>Number(p.id)!==Number(d.manager_employee_id)):members;return `<section class="department-column" data-department-column><header><span class="eyebrow">${esc(d.branch_name||'المؤسسة')}</span><h3>${esc(d.name)}</h3><small>${digits(members.length)} موظف · رئيس القسم: ${esc(d.manager_name||'غير معين')}</small><button type="button" data-toggle-department aria-label="طي القسم">−</button></header><div class="department-head-node">${head?executivePersonCard(head,d.manager_employee_id):'<span class="empty compact-empty">لم يحدد رئيس للقسم.</span>'}</div><div class="department-people">${staff.map(p=>executivePersonCard(p,d.manager_employee_id)).join('')||'<div class="empty compact-empty">لا يوجد موظفون أسفل رئيس القسم.</div>'}</div></section>`}).join('')||'<div class="empty">لا توجد أقسام تطابق التصفية.</div>'}</div></div></div>`}
  function fitOrganizationGrid(enable=state.orgFit){const viewport=$('#organizationTree'),stage=$('.org-fit-stage',viewport),grid=$('.executive-org-grid',viewport),button=$('#zoomOrganization');if(!stage||!grid)return;grid.style.position='relative';grid.style.inset='auto';grid.style.transform='none';stage.style.height='auto';stage.classList.remove('fitted');const naturalWidth=Math.ceil(grid.scrollWidth),naturalHeight=Math.ceil(grid.scrollHeight),availableWidth=Math.max(1,viewport.clientWidth-20);state.orgFit=Boolean(enable);state.orgZoom=state.orgFit?Math.max(.1,Math.min(1,availableWidth/Math.max(1,naturalWidth))):1;if(state.orgFit&&state.orgZoom<1){stage.classList.add('fitted');stage.style.height=Math.ceil(naturalHeight*state.orgZoom)+'px';grid.style.position='absolute';grid.style.inset='0 0 auto auto';grid.style.transform=`scale(${state.orgZoom})`}if(button){button.textContent=tr(state.orgFit?'الحجم الأصلي':'ملاءمة');button.setAttribute('aria-pressed',String(state.orgFit));button.dataset.scale=String(state.orgZoom);decorateActionButton(button,'expand')}}
