  function jobTitleModal(title=null){const editing=Boolean(title),selected=(a,b)=>String(a??'')===String(b??'')?'selected':'';openModal(editing?'تعديل مسمى وظيفي':'إضافة مسمى وظيفي',`<form id="jobTitleForm"><input type="hidden" name="reference_id" value="${title?.id||''}"><label>المسمى<input name="name" required maxlength="180" value="${esc(title?.name||'')}"></label><label>القسم المرجعي<select name="department_id"><option value="">كل الأقسام</option>${state.departments.map(d=>`<option value="${d.id}" ${selected(d.id,title?.department_id)}>${esc(d.name)}</option>`).join('')}</select></label>${editing?`<label class="check-line"><input name="active" type="checkbox" ${title.active===false?'':'checked'}> مسمى نشط ومتاح للاختيار</label>`:''}<button class="primary" type="submit">${editing?'حفظ التعديلات':'حفظ المسمى'}</button></form>`)}
