  async function toggleJobReference(kind,id){const item=(kind==='grade'?state.jobGrades:state.jobTitles).find(x=>String(x.id)===String(id));if(!item)return;try{await api(`/api/${kind==='grade'?'job-grades':'job-titles'}/${id}`,{method:'PATCH',body:{active:!item.active}});toast(item.active?'تم إيقاف المرجع':'تم تفعيل المرجع');await loadReferences()}catch(error){alertMessage(apiError(error),true)}}
