  function reportClock(value){if(!value)return '—';try{return i18n()?.formatDate(value,{hour:'2-digit',minute:'2-digit'})||String(value).slice(11,16)}catch(_){return String(value).slice(11,16)||value}}
  function reportStatus(domain,value){
    const labels={
      attendance:{working_day:'يوم عمل',weekly_rest:'راحة أسبوعية',open:'تسجيل مفتوح',no_shift:'لا توجد مناوبة',absent:'غائب'},
      action:{open:'مفتوح',closed:'مغلق',cancelled:'ملغي'},
      advance:{submitted:'مقدم',approved:'معتمد',rejected:'مرفوض',completed:'مكتمل',cancelled:'ملغي'},
      profile:{active:'نشط',inactive:'غير نشط'}
    };
    return tr(labels[domain]?.[value]||value||'—')
  }
  function reportPreserved(value){return `<span data-i18n-preserve>${esc(value??'—')}</span>`}
  function reportTable(title,columns,rows,emptyMessage='لا توجد سجلات ضمن الفترة المحددة.'){return `<section class="report-document-section"><div class="report-section-title"><span></span><h3>${tr(title)}</h3><b>${digits(rows.length)}</b></div>${rows.length?`<div class="report-document-table-wrap"><table class="report-document-table"><thead><tr>${columns.map(column=>`<th>${tr(column.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(column=>`<td data-label="${esc(tr(column.label))}">${column.render(row)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="report-document-empty">${tr(emptyMessage)}</div>`}</section>`}
  function reportMetric(label,value,detail,tone=''){return `<div class="report-summary-cell ${tone}"><small>${tr(label)}</small><b>${value}</b><span>${tr(detail)}</span></div>`}
  function loadEmployeeReportPage(){
    const today=new Date().toISOString().slice(0,10),to=$('#employeeReportTo');to.max=today;$('#employeeReportFrom').max=today;if(!to.value)to.value=today;
    if(state.employeeReportSelection){$('#employeeReportQuery').value=`${state.employeeReportSelection.full_name} · ${state.employeeReportSelection.employee_no}`;$('#employeeReportEmployeeId').value=state.employeeReportSelection.id;$('#clearEmployeeReportSearch').hidden=false;$('#employeeReportSearchStatus').textContent=`${tr('تم اختيار')} ${state.employeeReportSelection.full_name} · ${state.employeeReportSelection.employee_no}`}
    if(state.employeeReport)renderEmployeeReport(state.employeeReport);else{$('#employeeReportEmpty').hidden=false;$('#employeeReportLoading').hidden=true;$('#employeeReportResult').hidden=true}
  }
  function clearEmployeeReportSelection(clearQuery=true){state.employeeReportSelection=null;$('#employeeReportEmployeeId').value='';if(clearQuery)$('#employeeReportQuery').value='';$('#clearEmployeeReportSearch').hidden=true;$('#employeeReportSearchResults').hidden=true;$('#employeeReportQuery').setAttribute('aria-expanded','false');$('#employeeReportSearchStatus').textContent=tr('ابدأ بكتابة اسم الموظف أو رقمه الوظيفي.');if(clearQuery)$('#employeeReportQuery').focus()}
  async function searchEmployeeReports(){
    const input=$('#employeeReportQuery'),query=input.value.trim(),sequence=++state.employeeReportSearchSequence;
    clearTimeout(state.employeeReportSearchTimer);
    if(state.employeeReportSelection&&query!==`${state.employeeReportSelection.full_name} · ${state.employeeReportSelection.employee_no}`)clearEmployeeReportSelection(false);
    if(!query){$('#employeeReportSearchResults').hidden=true;input.setAttribute('aria-expanded','false');$('#employeeReportSearchStatus').textContent=tr('ابدأ بكتابة اسم الموظف أو رقمه الوظيفي.');return}
    $('#employeeReportSearchStatus').textContent=tr('جارٍ البحث…');
    state.employeeReportSearchTimer=setTimeout(async()=>{
      try{
        const response=await api(`/api/employee-reports/search?q=${encodeURIComponent(query)}`);
        if(sequence!==state.employeeReportSearchSequence)return;
        state.employeeReportSearch=items(response);
        const results=$('#employeeReportSearchResults');
        results.innerHTML=state.employeeReportSearch.length
          ?state.employeeReportSearch.map(employee=>`<button type="button" role="option" id="employee-report-option-${employee.id}" data-employee-report-option="${employee.id}" aria-selected="false"><span class="avatar">${esc(initials(employee.full_name))}</span><span data-i18n-preserve><b>${esc(employee.full_name)}</b><small>${esc(employee.employee_no)} · ${esc(employee.job_title||'—')} · ${esc(employee.department_name||'—')}</small></span><em class="status ${employee.active?'':'red'}">${tr(employee.active?'نشط':'غير نشط')}</em></button>`).join('')
          :`<div class="report-search-empty">${tr('لا يوجد موظف مطابق للاسم أو الرقم.')}</div>`;
        results.hidden=false;
        input.setAttribute('aria-expanded','true');
        $('#employeeReportSearchStatus').textContent=state.employeeReportSearch.length?`${digits(state.employeeReportSearch.length)} ${tr('نتيجة متاحة')}`:tr('لا توجد نتائج.');
      }catch(error){
        if(sequence!==state.employeeReportSearchSequence)return;
        $('#employeeReportSearchStatus').textContent=apiError(error);
        $('#employeeReportSearchResults').hidden=true;
      }
    },260)
  }
  function chooseEmployeeReport(employeeId){const employee=state.employeeReportSearch.find(item=>String(item.id)===String(employeeId));if(!employee)return;state.employeeReportSelection=employee;$('#employeeReportEmployeeId').value=employee.id;$('#employeeReportQuery').value=`${employee.full_name} · ${employee.employee_no}`;$('#employeeReportSearchResults').hidden=true;$('#employeeReportQuery').setAttribute('aria-expanded','false');$('#clearEmployeeReportSearch').hidden=false;const today=new Date().toISOString().slice(0,10);$('#employeeReportFrom').value=employee.hire_date&&employee.hire_date<=today?employee.hire_date:today;$('#employeeReportTo').value=today;$('#employeeReportSearchStatus').textContent=`${tr('تم اختيار')} ${employee.full_name} · ${employee.employee_no}`;$('#employeeReportError').hidden=true;$('#employeeReportFrom').focus()}
