    const employeeFacts=[['الرقم الوظيفي',employee.employee_no],['المسمى الوظيفي',employee.job_title||'—'],['الدرجة الوظيفية',[employee.job_grade,employee.job_grade_name].filter(Boolean).join(' · ')||'—'],['القسم',employee.department_name||'—'],['الفرع',employee.branch_name||'—'],['تاريخ التعيين',dateText(employee.hire_date)],['حالة الملف',reportStatus('profile',employee.active?'active':'inactive')]];
    const metrics=[reportMetric('صافي ساعات العمل',minutesText(summary.net_work_minutes),'بعد خصم الاستراحة'),reportMetric('الحضور المكتمل',digits(summary.attendance_completed_days),'يوم مكتمل'),reportMetric('التسجيل المفتوح',digits(summary.attendance_open_days),'يحتاج تسجيل خروج',summary.attendance_open_days?'warn':''),reportMetric('الغياب المستحق',digits(summary.absence_days),'يوم عمل','risk'),reportMetric('الراحة الأسبوعية',digits(summary.weekly_rest_days),'حسب المناوبة'),reportMetric('الإجازات المعتمدة',digits(summary.approved_leave_days),'يوم داخل الفترة'),reportMetric('العمل الإضافي',minutesText(summary.approved_overtime_minutes),'معتمد فقط'),reportMetric('التأخير',minutesText(summary.late_minutes),'بعد فترة السماح',summary.late_minutes?'warn':'')].join('');
    const attendance=reportTable('تفاصيل الحضور',[{label:'التاريخ',render:r=>dateText(r.work_date)},{label:'الدخول',render:r=>reportClock(r.check_in_at)},{label:'الخروج',render:r=>reportClock(r.check_out_at)},{label:'صافي العمل',render:r=>minutesText(r.net_minutes)},{label:'التأخير',render:r=>minutesText(r.late_minutes)},{label:'الحالة',render:r=>`<span class="report-inline-status">${esc(reportStatus('attendance',r.day_status))}</span>`}],report.attendance);
