    const actions=reportTable('المخالفات والتعهدات',[{label:'النوع',render:r=>tr(r.action_type==='violation'?'مخالفة':'تعهد')},{label:'التاريخ',render:r=>dateText(r.action_date)},{label:'الوصف',render:r=>reportPreserved(r.description)},{label:'الجزاء',render:r=>reportPreserved(r.penalty||'—')},{label:'الحالة',render:r=>reportStatus('action',r.status)}],report.actions);
    const overtime=reportTable('العمل الإضافي المعتمد',[{label:'التاريخ',render:r=>dateText(r.work_date)},{label:'من / إلى',render:r=>`<span dir="ltr">${esc(r.start_time)} - ${esc(r.end_time)}</span>`},{label:'المدة',render:r=>minutesText(r.duration_minutes)},{label:'السبب',render:r=>reportPreserved(r.reason)}],report.overtime);
    const advances=reportTable('السلف والأقساط',[{label:'مبلغ الاقتراض',render:r=>money(r.amount_cents/100)},{label:'تاريخ الطلب',render:r=>dateText(String(r.created_at).slice(0,10))},{label:'الأشهر',render:r=>digits(r.months)},{label:'الحالة',render:r=>reportStatus('advance',r.status)},{label:'المدفوع',render:r=>money(r.paid_cents/100)},{label:'المتبقي',render:r=>`<b>${money(r.remaining_cents/100)}</b>`},{label:'آخر استحقاق',render:r=>reportPreserved(r.last_due_month||'—')}],report.advances);
    const absence=report.absence.dates.length?`<section class="report-document-section absence-section"><div class="report-section-title"><span></span><h3>${tr('تواريخ الغياب المستحق')}</h3><b>${digits(report.absence.dates.length)}</b></div>${report.absence.dates.length>24?`<div class="absence-months">${report.absence.by_month.map(row=>`<span><b>${esc(row.month)}</b><small>${digits(row.days)} ${tr('يوم')}</small></span>`).join('')}</div>`:`<div class="absence-dates">${report.absence.dates.map(value=>`<time datetime="${esc(value)}">${dateText(value)}</time>`).join('')}</div>`}</section>`:'';
