  async function printEmployeeReport(){const report=state.employeeReport;if(!report)return;const button=$('#printEmployeeReport');button.disabled=true;try{await api(`/api/employees/${report.employee.id}/comprehensive-report/export`,{method:'POST',body:{date_from:report.period.requested_from,date_to:report.period.requested_to,format:'print_pdf',report_reference:report.report_reference}});const target=$('#employeeComprehensiveReport');target.classList.add('print-target');window.print();setTimeout(()=>target.classList.remove('print-target'),300)}catch(error){alertMessage(apiError(error),true)}finally{button.disabled=false}}
  async function loadReports(){const data=await api('/api/reports/summary'),s=data.summary||data;$('#reportMetrics').innerHTML=[['الموظفون النشطون',digits(s.employees),'من ملفات الموظفين'],['الفروع النشطة',digits(s.branches),'بنطاقات جغرافية'],['حضور اليوم',digits(s.attendance_today),'تسجيل دخول فعلي'],['طلبات معلقة',digits(Number(s.leave_pending)+Number(s.overtime_pending)),'إجازات وعمل إضافي'],['مسيرات الرواتب',digits(s.payroll_runs),'محفوظة في SQLite'],['صافي الرواتب المعتمدة',money(s.payroll_net),'من عناصر المسيرات']].map(metricHtml).join('');$('#reportAsOf').textContent=tr('حتى')+' '+i18n()?.formatDate(s.as_of,{dateStyle:'medium',timeStyle:'short'})}

