  async function syncAudience(){const type=$('#audienceType').value,label=$('#audienceRefLabel'),select=$('#audienceRef');label.hidden=type==='all';if(type==='department'){const d=items(await api('/api/departments'));select.innerHTML=d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}else if(type==='branch'){select.innerHTML=state.branches.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}else if(type==='employees'){select.innerHTML=state.employees.map(x=>`<option value="${x.id}">${esc(x.name||x.full_name)}</option>`).join('')}}
