  async function readNotification(id){const n=state.notifications.find(x=>String(x.id)===String(id));if(!n)return;openModal(n.title,`<article><span class="status">${esc(statusLabel(n.message_type))}</span><p style="font-size:14px;line-height:2">${esc(n.body)}</p><small>${esc(n.sender_name||'إدارة الموارد البشرية')} · ${esc(n.created_at||'')}</small></article>`);if(!n.read_at){try{await api(`/api/notifications/${id}/read`,{method:'POST'});n.read_at=new Date().toISOString();renderNotifications();updateUnread(state.notifications.filter(x=>!x.read_at).length)}catch(error){alertMessage(apiError(error),true)}}}

