  function fillCardSettingsForm(){const form=$('#cardSettingsForm'),o=state.org||{};if(!form)return;['card_template','card_primary_color','card_accent_color','card_back_instructions','card_contact_phone','card_contact_email'].forEach(key=>{if(form.elements[key])form.elements[key].value=o[key]||form.elements[key].value});$$('[data-card-template-choice]').forEach(button=>{const active=button.dataset.cardTemplateChoice===form.card_template.value;button.classList.toggle('active',active);button.setAttribute('aria-checked',String(active))})}
  function fitCardPreview(stage){if(!stage||stage.clientWidth===0||stage.offsetParent===null)return;const spread=$('.employee-card-spread',stage);if(!spread)return;spread.style.zoom='1';spread.style.position='absolute';spread.style.inset='auto';spread.style.transform='none';spread.style.transformOrigin='center center';const naturalWidth=Math.max(spread.scrollWidth,spread.offsetWidth),naturalHeight=Math.max(spread.scrollHeight,spread.offsetHeight),compact=window.innerWidth<=760,viewportHeight=compact?Math.min(760,Math.max(520,window.innerHeight*.78)):stage.id==='cardTemplatePreview'?Math.min(430,Math.max(280,window.innerHeight*.48)):Math.min(430,Math.max(230,window.innerHeight*.46)),availableWidth=Math.max(1,stage.clientWidth-32),availableHeight=Math.max(1,viewportHeight-28),scale=Math.min(1,availableWidth/naturalWidth,availableHeight/naturalHeight);stage.style.height=`${Math.ceil(viewportHeight)}px`;spread.style.left='50%';spread.style.top='50%';spread.style.transform=`translate(-50%,-50%) scale(${scale.toFixed(4)})`;spread.dataset.previewScale=scale.toFixed(4);stage.classList.toggle('scaled-preview',scale<.999)}
