  function fileData(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('صيغة الصورة غير مدعومة.'));if(file.size>1.5*1024*1024)return reject(new Error('حجم الصورة يتجاوز ١٫٥ م.ب.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('تعذر قراءة الصورة.'));r.readAsDataURL(file)})}
